    /// Where a header/footer of this kind lives, and how to declare it.
    ///
    /// All four public entry points differ only in what goes *inside* the part;
    /// the surrounding bookkeeping — part name, content type, relationship,
    /// section reference — is identical, and lives here.
    ///
    /// Note the fixed `1` in the part name: rdocx manages one header and one
    /// footer per [`HdrFtrType`] for the document's single section. Setting a
    /// header of the same type again replaces the existing part.
    fn hdr_ftr_slot_metadata(
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> (String, &'static str, &'static str) {
        let type_suffix = match hdr_type {
            HdrFtrType::Default => "",
            HdrFtrType::First => "First",
            HdrFtrType::Even => "Even",
        };
        if is_header {
            (
                format!("/word/header{type_suffix}1.xml"),
                rel_types::HEADER,
                "application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml",
            )
        } else {
            (
                format!("/word/footer{type_suffix}1.xml"),
                rel_types::FOOTER,
                "application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml",
            )
        }
    }

    /// Install a header/footer part: store its bytes, declare the content type,
    /// relate it to the document, and point the section properties at it.
    ///
    /// Any previous reference of the same [`HdrFtrType`] is replaced.
    fn reserve_hdr_ftr_part_name(
        &mut self,
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> Result<String> {
        self.identifiers.observe_package_graph(&self.package)?;
        let (preferred, expected_rel_type, _) = Self::hdr_ftr_slot_metadata(is_header, hdr_type);
        let reference = self.document.body.sect_pr.as_ref().and_then(|section| {
            let references = if is_header {
                &section.header_refs
            } else {
                &section.footer_refs
            };
            references
                .iter()
                .find(|reference| reference.hdr_ftr_type == hdr_type)
        });
        if let Some(part_name) = reference
            .and_then(|reference| {
                self.package
                    .get_part_rels(&self.doc_part_name)
                    .and_then(|relationships| relationships.get_by_id(&reference.rel_id))
            })
            .filter(|relationship| {
                relationship.rel_type == expected_rel_type && relationship_is_internal(relationship)
            })
            .map(|relationship| {
                OpcPackage::resolve_rel_target(&self.doc_part_name, &relationship.target)
            })
        {
            return Ok(part_name);
        }
        self.identifiers.reserve_preferred_part_name(&preferred)
    }

    fn install_hdr_ftr_part(
        &mut self,
        part_name: String,
        xml: Vec<u8>,
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> Result<String> {
        let (_, rel_type, content_type) = Self::hdr_ftr_slot_metadata(is_header, hdr_type);

        // Setting the same header twice must not leave the first relationship
        // behind pointing at the same part.
        let rel_target = relative_target(&self.doc_part_name, &part_name);
        let existing = self
            .package
            .get_part_rels(&self.doc_part_name)
            .and_then(|rels| {
                rels.items
                    .iter()
                    .find(|relationship| {
                        relationship.rel_type == rel_type
                            && relationship_is_internal(relationship)
                            && OpcPackage::resolve_rel_target(
                                &self.doc_part_name,
                                &relationship.target,
                            ) == part_name
                    })
                    .map(|relationship| relationship.id.clone())
            });
        let pending_relationship = match existing {
            Some(existing) => (existing, false),
            None => (
                self.identifiers
                    .reserve_relationship_id_checked(&self.doc_part_name)
                    .map_err(|error| {
                        Error::Other(format!(
                            "header or footer relationship allocation failed: {error}"
                        ))
                    })?,
                true,
            ),
        };

        self.package.set_part(&part_name, xml);
        self.identifiers
            .authored_story_parts
            .insert(part_name.clone());
        self.package
            .content_types
            .add_override(&part_name, content_type);
        self.identifiers.register_content_type_override(&part_name);
        let (rel_id, install_relationship) = pending_relationship;
        if install_relationship {
            self.package
                .get_or_create_part_rels(&self.doc_part_name)
                .add_with_id(&rel_id, rel_type, &rel_target);
        }

        let sect = self.section_properties_mut();
        let refs = if is_header {
            &mut sect.header_refs
        } else {
            &mut sect.footer_refs
        };
        refs.retain(|r| r.hdr_ftr_type != hdr_type);
        refs.push(HdrFtrRef {
            hdr_ftr_type: hdr_type,
            rel_id,
        });

        Ok(part_name)
    }

    fn clear_authored_story_relationships(&mut self, part_name: &str) {
        self.prune_authored_story_relationships(part_name, &HashSet::new());
    }

    fn prune_authored_story_relationships(
        &mut self,
        part_name: &str,
        referenced: &HashSet<String>,
    ) {
        let preserved = self
            .identifiers
            .preserved_relationship_ids
            .get(&relationship_owner_identity(part_name))
            .cloned()
            .unwrap_or_default();
        let Some(relationships) = self.package.get_part_rels_mut(part_name) else {
            return;
        };
        let mut removed = Vec::new();
        relationships.items.retain(|relationship| {
            if preserved.contains(&relationship.id) || referenced.contains(&relationship.id) {
                true
            } else {
                removed.push(relationship.clone());
                false
            }
        });
        let relationships_are_empty = relationships.items.is_empty();
        if relationships_are_empty {
            self.package.remove_part_rels(part_name);
        }
        self.identifiers.retire_authored_story_relationships(
            part_name,
            removed.iter().map(|relationship| relationship.id.clone()),
        );
        self.remove_unreachable_image_parts(part_name, &removed);
    }

    /// Drop image relationships of `owner` that the removed content named and
    /// that no remaining attribute names. A part the owner did not name before
    /// the edit stays, as does every non-image relationship.
    fn release_unreferenced_images(
        &mut self,
        owner: &str,
        referenced_before: &HashSet<String>,
        referenced_after: &HashSet<String>,
    ) {
        let Some(relationships) = self.package.get_part_rels_mut(owner) else {
            return;
        };
        let mut removed = Vec::new();
        relationships.items.retain(|relationship| {
            let released = relationship.rel_type == rel_types::IMAGE
                && relationship_is_internal(relationship)
                && referenced_before.contains(&relationship.id)
                && !referenced_after.contains(&relationship.id);
            if released {
                removed.push(relationship.clone());
            }
            !released
        });
        if removed.is_empty() {
            return;
        }
        if relationships.items.is_empty() {
            self.package.remove_part_rels(owner);
        }
        if let Some(preserved) = self
            .identifiers
            .preserved_relationship_ids
            .get_mut(&relationship_owner_identity(owner))
        {
            for relationship in &removed {
                preserved.remove(&relationship.id);
            }
        }
        self.identifiers.retire_authored_story_relationships(
            owner,
            removed.iter().map(|relationship| relationship.id.clone()),
        );
        for relationship in &removed {
            self.identifiers
                .preserved_part_names
                .remove(&part_name_identity(&OpcPackage::resolve_rel_target(
                    owner,
                    &relationship.target,
                )));
        }
        self.remove_unreachable_image_parts(owner, &removed);
    }

    /// Remove internal image targets that no remaining relationship reaches.
    fn remove_unreachable_image_parts(
        &mut self,
        part_name: &str,
        removed: &[oxml_opc::relationship::Relationship],
    ) {
        let mut image_parts = removed
            .iter()
            .filter(|relationship| {
                relationship.rel_type == rel_types::IMAGE && relationship_is_internal(relationship)
            })
            .map(|relationship| OpcPackage::resolve_rel_target(part_name, &relationship.target))
            .collect::<HashSet<_>>();
        image_parts.retain(|candidate| {
            !self.package.part_rels.iter().any(|(owner, relationships)| {
                relationships.items.iter().any(|relationship| {
                    relationship_is_internal(relationship)
                        && OpcPackage::resolve_rel_target(owner, &relationship.target) == *candidate
                })
            })
        });
        for image_part in image_parts {
            if self.identifiers.part_is_preserved(&image_part) {
                continue;
            }
            self.package.remove_part(&image_part);
            self.package.remove_part_rels(&image_part);
            self.package.content_types.remove_override(&image_part);
            self.identifiers.retire_authored_part(&image_part);
            let Some((_, extension)) = image_part.rsplit_once('.') else {
                continue;
            };
            let default_is_used = self.package.parts.keys().any(|part_name| {
                !self.package.content_types.contains_override(part_name)
                    && part_name
                        .rsplit_once('.')
                        .is_some_and(|(_, candidate)| candidate == extension)
            });
            if !default_is_used
                && self
                    .identifiers
                    .authored_content_type_defaults
                    .remove(extension)
            {
                self.package.content_types.remove_default(extension);
                self.identifiers.content_type_defaults.remove(extension);
            }
        }
    }

    /// Serialize a header/footer body, choosing the right root element.
    fn serialize_hdr_ftr(hdr_ftr: &CT_HdrFtr, is_header: bool) -> Result<Vec<u8>> {
        let xml = if is_header {
            hdr_ftr.to_xml_header()
        } else {
            hdr_ftr.to_xml_footer()
        };
        Ok(xml?)
    }

    fn set_header_footer_part(
        &mut self,
        text: &str,
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> Result<()> {
        let mut hdr_ftr = CT_HdrFtr::new();
        let mut p = CT_P::new();
        if !text.is_empty() {
            p.add_run(text);
        }
        hdr_ftr.paragraphs.push(p);

        let xml = Self::serialize_hdr_ftr(&hdr_ftr, is_header)?;
        let part_name = self.reserve_hdr_ftr_part_name(is_header, hdr_type)?;
        self.clear_authored_story_relationships(&part_name);
        self.install_hdr_ftr_part(part_name, xml, is_header, hdr_type)?;
        Ok(())
    }

    fn set_raw_hdr_ftr_with_images(
        &mut self,
        xml: Vec<u8>,
        images: &[(&str, &[u8], &str)],
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> Result<()> {
        let part_name = self.reserve_hdr_ftr_part_name(is_header, hdr_type)?;
        let mut requested = HashSet::new();
        for &(rel_id, _, _) in images {
            if !requested.insert(rel_id) {
                return Err(Error::Other(format!(
                    "duplicate supplied header or footer relationship id {rel_id}"
                )));
            }
        }
        self.clear_authored_story_relationships(&part_name);
        let mut relationship_remap = HashMap::new();
        for &(rel_id, _, _) in images {
            let allocated = self
                .identifiers
                .reserve_requested_relationship_id_checked(&part_name, rel_id)
                .map_err(|error| {
                    Error::Other(format!(
                        "header or footer image relationship allocation failed: {error}"
                    ))
                })?;
            if allocated != rel_id {
                relationship_remap.insert(rel_id.to_owned(), allocated);
            }
        }
        let xml = remap_xml_relationship_ids(&xml, &relationship_remap)?;
        let part_name = self.install_hdr_ftr_part(part_name, xml, is_header, hdr_type)?;

        for &(rel_id, image_data, image_filename) in images {
            let img_rel_target = self.store_image_part(image_data, image_filename);
            let allocated = relationship_remap
                .get(rel_id)
                .map_or(rel_id, String::as_str);
            self.package
                .get_or_create_part_rels(&part_name)
                .add_with_id(allocated, rel_types::IMAGE, &img_rel_target);
        }
        Ok(())
    }

    fn set_header_footer_image_part(
        &mut self,
        image_data: &[u8],
        image_filename: &str,
        width: Length,
        height: Length,
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> Result<()> {
        self.set_header_footer_image_bg_part(
            image_data,
            image_filename,
            width,
            height,
            None,
            is_header,
            hdr_type,
        )
    }

    fn set_header_footer_image_bg_part(
        &mut self,
        image_data: &[u8],
        image_filename: &str,
        width: Length,
        height: Length,
        bg_color: Option<&str>,
        is_header: bool,
        hdr_type: HdrFtrType,
    ) -> Result<()> {
        use rdocx_oxml::properties::CT_Shd;

        let part_name = self.reserve_hdr_ftr_part_name(is_header, hdr_type)?;
        self.clear_authored_story_relationships(&part_name);

        let img_rel_id = self
            .add_image_relationship_checked(&part_name, image_data, image_filename)
            .map_err(|error| {
                Error::Other(format!(
                    "header or footer image relationship allocation failed: {error}"
                ))
            })?;

        let mut inline = CT_Inline::new(&img_rel_id, width.to_emu(), height.to_emu());
        inline.doc_pr_id = self.identifiers.reserve_drawing_id()?;
        let run = CT_R {
            alt_drawings: Vec::new(),
            properties: None,
            content: vec![RunContent::Drawing(CT_Drawing::inline(inline))],
            extra_xml: Vec::new(),
            extra_xml_positions: Vec::new(),
        };

        let mut p = CT_P::new();
        p.runs.push(run);
        if let Some(color) = bg_color {
            p.properties = Some(CT_PPr {
                shading: Some(Box::new(CT_Shd {
                    val: "clear".to_string(),
                    color: Some("auto".to_string()),
                    fill: Some(color.to_string()),
                    ..Default::default()
                })),
                ..Default::default()
            });
        }

        let mut hdr_ftr = CT_HdrFtr::new();
        hdr_ftr.paragraphs.push(p);

        let xml = Self::serialize_hdr_ftr(&hdr_ftr, is_header)?;
        self.install_hdr_ftr_part(part_name, xml, is_header, hdr_type)?;
        Ok(())
    }

    fn get_header_footer_text(&self, is_header: bool, hdr_type: HdrFtrType) -> Option<String> {
        let sect = self.document.body.sect_pr.as_ref()?;
        let refs = if is_header {
            &sect.header_refs
        } else {
            &sect.footer_refs
        };
        let reference = self.first_usable_header_footer_reference(refs, hdr_type, is_header)?;
        Some(
            self.load_header_footer(&reference.rel_id, is_header)?
                .text(),
        )
    }

    // ---- Numbering/Lists ----

    /// Ensure a numbering part exists.
    ///
    /// The relationship and content-type override are added by
    /// [`Self::flush_to_package`], which knows the resolved part name and will
    /// not create a second numbering relationship if one already exists.
    fn ensure_numbering(&mut self) -> &mut CT_Numbering {
        self.numbering.get_or_insert_with(CT_Numbering::new)
    }

    fn reserve_numbering_bundle(&mut self) -> Result<()> {
        self.identifiers.observe_package_graph(&self.package)?;
        if let Some(numbering) = &self.numbering {
            self.identifiers.abstract_numbering_ids.extend(
                numbering
                    .abstract_nums
                    .iter()
                    .map(|definition| definition.abstract_num_id),
            );
            self.identifiers
                .numbering_instance_ids
                .extend(numbering.nums.iter().map(|instance| instance.num_id));
        }
        let part_name = match self.numbering_part_name.as_deref() {
            Some(part_name) => part_name.to_owned(),
            None => self
                .identifiers
                .reserve_preferred_part_name(DEFAULT_NUMBERING_PART)?,
        };
        let already_linked =
            self.package
                .get_part_rels(&self.doc_part_name)
                .is_some_and(|relationships| {
                    relationships.items.iter().any(|relationship| {
                        relationship.rel_type == rel_types::NUMBERING
                            && relationship_is_internal(relationship)
                            && OpcPackage::resolve_rel_target(
                                &self.doc_part_name,
                                &relationship.target,
                            ) == part_name
                    })
                });
        let pending_id = if already_linked {
            None
        } else {
            Some(
                self.identifiers
                    .reserve_bundle_relationship_id_checked(
                        &self.doc_part_name,
                        rel_types::NUMBERING,
                    )
                    .map_err(|error| {
                        Error::Other(format!("numbering relationship allocation failed: {error}"))
                    })?,
            )
        };
        self.package
            .content_types
            .add_override(&part_name, NUMBERING_CONTENT_TYPE);
        self.identifiers.register_content_type_override(&part_name);
        if let Some(id) = pending_id {
            let target = relative_target(&self.doc_part_name, &part_name);
            self.package
                .get_or_create_part_rels(&self.doc_part_name)
                .add_with_id(&id, rel_types::NUMBERING, &target);
        }
        self.numbering_part_name = Some(part_name);
        Ok(())
    }

    fn reserve_styles_bundle(&mut self) -> Result<()> {
        let existing = self.styles_part_name.clone();
        let part_name = self
            .reserve_document_part_bundle(
                existing.as_deref(),
                DEFAULT_STYLES_PART,
                rel_types::STYLES,
                STYLES_CONTENT_TYPE,
            )
            .map_err(|error| {
                Error::Other(format!("styles relationship allocation failed: {error}"))
            })?;
        self.styles_part_name = Some(part_name);
        Ok(())
    }

    fn reserve_footnotes_bundle(&mut self) -> Result<()> {
        let existing = self.footnotes_part_name.clone();
        let part_name = self
            .reserve_document_part_bundle(
                existing.as_deref(),
                "/word/footnotes.xml",
                rel_types::FOOTNOTES,
                "application/vnd.openxmlformats-officedocument.wordprocessingml.footnotes+xml",
            )
            .map_err(|error| {
                Error::Other(format!("footnotes relationship allocation failed: {error}"))
            })?;
        self.footnotes_part_name = Some(part_name);
        Ok(())
    }

    /// The direct ASCII document default font, without changing Normal.
    pub fn default_font_name(&self) -> Option<&str> {
        self.styles
            .doc_defaults
            .as_ref()?
            .rpr
            .as_ref()?
            .font_ascii
            .as_deref()
    }

    /// Stage a general four-slot default-font update, preserving unrelated defaults.
    pub fn set_default_font_name_value(&mut self, name: Option<&str>) -> Result<()> {
        if name.is_none()
            && self
                .styles
                .doc_defaults
                .as_ref()
                .and_then(|value| value.rpr.as_ref())
                .is_none()
        {
            return Ok(());
        }
        if let Some(name) = name {
            oxml_core::xml::reject_non_xml_characters("default_font_name", name)?;
        }
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        let defaults = candidate
            .styles
            .doc_defaults
            .get_or_insert_with(Default::default);
        let properties = defaults.rpr.get_or_insert_with(Default::default);
        properties.font_ascii = name.map(str::to_owned);
        properties.font_hansi = name.map(str::to_owned);
        properties.font_east_asia = name.map(str::to_owned);
        properties.font_cs = name.map(str::to_owned);
        properties.font_ascii_theme = None;
        properties.font_hansi_theme = None;
        properties.font_east_asia_theme = None;
        properties.font_cs_theme = None;
        if candidate.styles == self.styles {
            return Ok(());
        }
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// The normal-script direct default font size.
    pub fn default_font_size(&self) -> Option<Length> {
        self.styles
            .doc_defaults
            .as_ref()?
            .rpr
            .as_ref()?
            .sz
            .map(|size| Length::pt(size.to_pt()))
    }

    /// Set both normal and complex-script half-point defaults after preflight.
    pub fn set_default_font_size_value(&mut self, size: Option<Length>) -> Result<()> {
        let half_points = size
            .map(|size| {
                if size.to_emu() < 0 {
                    return Err(Error::Other(
                        "default_font_size cannot be negative".to_owned(),
                    ));
                }
                u32::try_from(size.to_emu() / 6350)
                    .map(rdocx_oxml::units::HalfPoint)
                    .map_err(|_| {
                        Error::Other("default_font_size exceeds half-point range".to_owned())
                    })
            })
            .transpose()?;
        if size.is_none()
            && self
                .styles
                .doc_defaults
                .as_ref()
                .and_then(|value| value.rpr.as_ref())
                .is_none()
        {
            return Ok(());
        }
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        let defaults = candidate
            .styles
            .doc_defaults
            .get_or_insert_with(Default::default);
        let properties = defaults.rpr.get_or_insert_with(Default::default);
        properties.sz = half_points;
        properties.sz_cs = half_points;
        if candidate.styles == self.styles {
            return Ok(());
        }
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// The document default paragraph properties, `w:pPrDefault`.
    ///
    /// The value is the stored `CT_PPr`, including every parsed line rule.
    pub fn default_paragraph_properties(&self) -> Option<&CT_PPr> {
        self.styles.doc_defaults.as_ref()?.ppr.as_ref()
    }

    /// Replace `w:pPrDefault`. `None` removes the paragraph defaults and
    /// keeps `w:rPrDefault` plus unrelated `w:docDefaults` source.
    pub fn set_default_paragraph_properties(&mut self, properties: Option<CT_PPr>) -> Result<()> {
        if self.default_paragraph_properties() == properties.as_ref() {
            return Ok(());
        }
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        candidate
            .styles
            .doc_defaults
            .get_or_insert_with(Default::default)
            .ppr = properties;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// The package a save would write now, staged on a copy.
    fn staged_output_package(&self) -> Result<OpcPackage> {
        self.validate_model_resource_limits()?;
        let mut candidate = self.clone_for_staging();
        candidate.prepare_staged_output()?;
        crate::embedded::persist_invalidated_package_signature(
            &mut candidate.package,
            candidate.package_signatures_invalidated,
        )?;
        Ok(candidate.package)
    }

    /// Package part names a save would write, each with a leading slash,
    /// in lexicographic order. The order includes parts with no relationship.
    pub fn part_names(&self) -> Result<Vec<String>> {
        let mut names = self
            .staged_output_package()?
            .parts
            .into_keys()
            .collect::<Vec<_>>();
        names.sort();
        Ok(names)
    }

    /// UTF-8 XML of one package part as a save would write it now.
    ///
    /// The name may omit its leading slash and matches without regard to
    /// case. A missing, binary, or non-UTF-8 part returns an error that names
    /// the part and its content type. A UTF-8 BOM is stripped. UTF-16 is not
    /// decoded.
    pub fn part_xml(&self, part_name: &str) -> Result<String> {
        let requested = format!(
            "/{}",
            part_name
                .trim()
                .strip_prefix('/')
                .unwrap_or(part_name.trim())
        );
        let package = self.staged_output_package()?;
        let Some(stored) = package
            .parts
            .keys()
            .find(|name| name.eq_ignore_ascii_case(&requested))
            .cloned()
        else {
            let content_type = package
                .content_types
                .content_type_for(&requested)
                .unwrap_or("none");
            return Err(Error::Other(format!(
                "part {requested} is missing (content type {content_type})"
            )));
        };
        let content_type = package
            .content_types
            .content_type_for(&stored)
            .unwrap_or("none");
        let data = package.get_part(&stored).expect("listed package part");
        let xml_type = content_type.to_ascii_lowercase().contains("xml");
        if !xml_type {
            return Err(Error::Other(format!(
                "part {stored} has content type {content_type} and is not UTF-8 XML"
            )));
        }
        let body = data.strip_prefix(b"\xEF\xBB\xBF").unwrap_or(data);
        // UTF-16 text without a BOM is ASCII bytes interleaved with NUL.
        // Those bytes are valid UTF-8, and XML 1.0 forbids NUL, so a NUL is
        // the non-UTF-8 refusal for an XML content type.
        let Ok(xml) = String::from_utf8(body.to_vec()) else {
            return Err(Error::Other(format!(
                "part {stored} has content type {content_type} and is not UTF-8 XML"
            )));
        };
        if xml.contains('\0') {
            return Err(Error::Other(format!(
                "part {stored} has content type {content_type} and is not UTF-8 XML"
            )));
        }
        Ok(xml)
    }

    /// Add a bullet list item at the given indentation level (0-based).
    ///
    /// If no bullet list definition exists yet, one is created automatically.
    /// Returns a mutable `Paragraph` for further configuration.
    pub fn add_bullet_list_item(&mut self, text: &str, level: u32) -> Paragraph<'_> {
        self.try_add_bullet_list_item(text, level)
            .expect("the historical infallible list helper requires a valid document and level")
    }

    /// Checked counterpart. Invalid text, levels and package graphs leave the document unchanged.
    pub fn try_add_bullet_list_item(&mut self, text: &str, level: u32) -> Result<Paragraph<'_>> {
        if level > 8 {
            return Err(Error::Other(
                "list level must be between 0 and 8".to_owned(),
            ));
        }
        oxml_core::xml::reject_non_xml_characters("text", text)?;
        self.validate_numbering_graph()?;
        let mut candidate = self.clone_for_staging();
        candidate.reserve_numbering_bundle()?;
        candidate.invalidate_layout();
        // Find or create a bullet list numId
        let existing = candidate.numbering.as_ref().and_then(|numbering| {
            numbering.nums.iter().find(|n| {
                numbering
                    .get_abstract_num_for(n.num_id)
                    .map(|a| {
                        a.levels.first().and_then(|l| l.num_fmt.as_ref())
                            == Some(&rdocx_oxml::numbering::ST_NumberFormat::Bullet)
                    })
                    .unwrap_or(false)
            })
        });
        let num_id = if let Some(existing) = existing {
            existing.num_id
        } else {
            let (abstract_id, num_id) = candidate.identifiers.reserve_numbering_ids()?;
            candidate.ensure_numbering().add_list_with_ids(
                &[(rdocx_oxml::numbering::ST_NumberFormat::Bullet, Some(1))],
                abstract_id,
                num_id,
            )
        };

        let mut p = CT_P::new();
        if !text.is_empty() {
            p.add_run(text);
        }
        let ppr = CT_PPr {
            num_id: Some(num_id),
            num_ilvl: Some(level),
            ..Default::default()
        };
        p.properties = Some(ppr);

        candidate
            .document
            .body
            .content
            .push(BodyContent::Paragraph(Box::new(p)));
        candidate.validate_numbering_graph()?;
        self.commit_staged_mutation(candidate);
        match self.document.body.content.last_mut().unwrap() {
            BodyContent::Paragraph(p) => Ok(Paragraph { inner: p }),
            _ => unreachable!(),
        }
    }

    /// Add a numbered list item at the given indentation level (0-based).
    ///
    /// If no numbered list definition exists yet, one is created automatically.
    /// Returns a mutable `Paragraph` for further configuration.
    pub fn add_numbered_list_item(&mut self, text: &str, level: u32) -> Paragraph<'_> {
        self.try_add_numbered_list_item(text, level)
            .expect("the historical infallible list helper requires a valid document and level")
    }

    /// Checked counterpart. Invalid text, levels and package graphs leave the document unchanged.
    pub fn try_add_numbered_list_item(&mut self, text: &str, level: u32) -> Result<Paragraph<'_>> {
        self.try_add_numbered_list_item_with_restart(text, level, false)
    }

    /// Checked numbered authoring with persisted explicit restart continuation.
    pub fn try_add_numbered_list_item_with_restart(
        &mut self,
        text: &str,
        level: u32,
        restart: bool,
    ) -> Result<Paragraph<'_>> {
        if level > 8 {
            return Err(Error::Other(
                "list level must be between 0 and 8".to_owned(),
            ));
        }
        oxml_core::xml::reject_non_xml_characters("text", text)?;
        self.validate_numbering_graph()?;
        let mut candidate = self.clone_for_staging();
        candidate.reserve_numbering_bundle()?;
        candidate.invalidate_layout();
        // Find or create a numbered list numId
        let existing = candidate.numbering.as_ref().and_then(|numbering| {
            numbering.nums.iter().find(|instance| {
                numbering
                    .get_abstract_num_for(instance.num_id)
                    .is_some_and(|definition| {
                        definition
                            .levels
                            .first()
                            .and_then(|value| value.num_fmt.as_ref())
                            == Some(&ST_NumberFormat::Decimal)
                    })
                    && !matches!(
                        candidate.effective_numbering_format(instance.num_id, level),
                        Some("bullet" | "none")
                    )
            })
        });
        let continuation = candidate
            .document
            .body
            .content
            .iter()
            .rev()
            .filter_map(|item| {
                let BodyContent::Paragraph(p) = item else {
                    return None;
                };
                let properties = p.properties.as_ref()?;
                let id = properties.num_id?;
                if properties.num_ilvl != Some(level) {
                    return None;
                }
                let instance = candidate
                    .numbering
                    .as_ref()?
                    .nums
                    .iter()
                    .find(|n| n.num_id == id)?;
                (candidate
                    .effective_numbering_format(id, level)
                    .is_some_and(|name| name == "decimal")
                    && instance
                        .level_overrides
                        .iter()
                        .any(|v| v.ilvl == level && v.start_override.is_some()))
                .then_some(id)
            })
            .next();
        let num_id = if let Some(id) = continuation {
            id
        } else if let Some(existing) = existing {
            existing.num_id
        } else {
            let (abstract_id, num_id) = candidate.identifiers.reserve_numbering_ids()?;
            candidate.ensure_numbering().add_list_with_ids(
                &[(rdocx_oxml::numbering::ST_NumberFormat::Decimal, Some(1))],
                abstract_id,
                num_id,
            )
        };

        let mut p = CT_P::new();
        if !text.is_empty() {
            p.add_run(text);
        }
        let ppr = CT_PPr {
            num_id: Some(num_id),
            num_ilvl: Some(level),
            ..Default::default()
        };
        p.properties = Some(ppr);

        candidate
            .document
            .body
            .content
            .push(BodyContent::Paragraph(Box::new(p)));
        if restart {
            let index = candidate.paragraph_count() - 1;
            candidate.restart_numbering(index, 1)?;
        }
        candidate.validate_numbering_graph()?;
        self.commit_staged_mutation(candidate);
        match self.document.body.content.last_mut().unwrap() {
            BodyContent::Paragraph(p) => Ok(Paragraph { inner: p }),
            _ => unreachable!(),
        }
    }

    /// Restart one current direct-body numbered paragraph without changing its peers.
    pub fn restart_numbering(&mut self, paragraph: usize, start: u32) -> Result<u32> {
        if self.content_index_of_paragraph(paragraph).is_none() {
            return Err(Error::Other(
                "numbering restart requires a direct body paragraph".into(),
            ));
        }
        self.validate_numbering_graph()?;
        let properties = self
            .paragraph(paragraph)
            .and_then(|p| p.inner.properties.as_ref())
            .ok_or_else(|| Error::Other("paragraph has no explicit numbering".into()))?;
        let (id, level) = properties
            .num_id
            .zip(properties.num_ilvl)
            .ok_or_else(|| Error::Other("paragraph has no explicit numbering level".into()))?;
        if level > 8
            || self
                .effective_numbering_format(id, level)
                .is_none_or(|name| matches!(name, "bullet" | "none"))
        {
            return Err(Error::Other(
                "numbering restart requires a numbered non-bullet level".into(),
            ));
        }
        let mut instance = self
            .numbering_instance(id)
            .ok_or_else(|| Error::Other("numbering instance is absent".into()))?;
        if instance.has_unmodeled_properties {
            return Err(Error::Other(
                "numbering restart cannot project unsupported override source".into(),
            ));
        }
        if let Some(value) = instance
            .level_overrides
            .iter_mut()
            .find(|v| v.level == level)
        {
            value.start = Some(start);
        } else {
            instance
                .level_overrides
                .push(NumberingLevelOverride::new(level).start(start));
        }
        let mut candidate = self.clone_for_staging();
        let new_id =
            candidate.add_numbering_instance(instance.definition_id, &instance.level_overrides)?;
        candidate
            .paragraph_mut(paragraph)
            .ok_or_else(|| Error::Other("numbering paragraph disappeared".into()))?
            .set_numbering(new_id, level);
        candidate.validate_numbering_graph()?;
        self.commit_staged_mutation(candidate);
        Ok(new_id)
    }

    /// Create a list definition with explicit per-level formats and return
    /// its numId.
    ///
    /// Unlike [`Self::add_bullet_list_item`] / [`Self::add_numbered_list_item`],
    /// which share one bullet and one numbered definition per document, every
    /// call creates a fresh definition — so separate lists restart their
    /// numbering, and one definition can mix formats across levels (e.g. a
    /// bullet list whose nested level is decimal). Attach paragraphs with
    /// [`crate::Paragraph::set_numbering`].
    ///
    /// `levels[i]` configures level `i`; deeper unspecified levels fall back
    /// to the standard template rotation for the last specified format's
    /// family. An empty slice produces the standard numbered template. Word
    /// supports nine levels, so entries after index eight are ignored.
    ///
    /// ```no_run
    /// use rdocx::{Document, ListLevel};
    ///
    /// let mut doc = Document::new();
    /// let num_id = doc.add_list_definition(&[
    ///     ListLevel::bullet(),
    ///     ListLevel::decimal().start(3),
    /// ]);
    /// doc.add_paragraph("first bullet").set_numbering(num_id, 0);
    /// doc.add_paragraph("third decimal").set_numbering(num_id, 1);
    /// ```
    pub fn add_list_definition(&mut self, levels: &[ListLevel]) -> u32 {
        if levels
            .iter()
            .take(9)
            .enumerate()
            .any(|(level, value)| validate_list_level(level as u32, value).is_err())
        {
            return 0;
        }
        let mut candidate = self.clone_for_staging();
        candidate
            .reserve_numbering_bundle()
            .expect("an in-memory document can allocate a numbering part");
        candidate.invalidate_layout();
        let formats: Vec<(ST_NumberFormat, Option<u32>)> = levels
            .iter()
            .take(9)
            .map(|level| (level.format.to_st(), level.start))
            .collect();
        let (abstract_id, num_id) = candidate
            .identifiers
            .reserve_numbering_ids()
            .expect("an in-memory document cannot exhaust numbering identifiers");
        let num_id = candidate
            .ensure_numbering()
            .add_list_with_ids(&formats, abstract_id, num_id);
        if let Some(definition) = candidate.numbering.as_mut().and_then(|numbering| {
            numbering
                .abstract_nums
                .iter_mut()
                .find(|definition| definition.abstract_num_id == abstract_id)
        }) {
            for (level, value) in levels.iter().take(9).enumerate() {
                let existing = &definition.levels[level];
                definition.levels[level] = merge_list_level(existing, value)
                    .expect("list level was validated before staged allocation");
            }
        }
        if candidate.validate_numbering_graph().is_err() {
            return 0;
        }
        self.commit_staged_mutation(candidate);
        num_id
    }

    /// Inspect all abstract numbering definitions in package order.
    pub fn numbering_definitions(&self) -> Vec<NumberingDefinition> {
        self.numbering
            .as_ref()
            .map(|numbering| {
                numbering
                    .abstract_nums
                    .iter()
                    .map(|definition| NumberingDefinition {
                        id: definition.abstract_num_id,
                        levels: definition
                            .levels
                            .iter()
                            .map(|level| NumberingDefinitionLevel {
                                level: level.ilvl,
                                properties: list_level_from_ct(level),
                            })
                            .collect(),
                        paragraph_style_links: definition
                            .levels
                            .iter()
                            .map(|level| level.p_style.clone())
                            .collect(),
                        has_unmodeled_properties: !definition.extra_xml.is_empty()
                            || !definition.extra_attributes.is_empty()
                            || definition
                                .nsid_raw
                                .as_ref()
                                .is_some_and(|(_, raw, prefixes)| {
                                    typed_numbering_leaf_has_unmodeled(raw, prefixes)
                                })
                            || definition.multi_level_type_raw.as_ref().is_some_and(
                                |(_, raw, prefixes)| {
                                    typed_numbering_leaf_has_unmodeled(raw, prefixes)
                                },
                            )
                            || definition
                                .tmpl_raw
                                .as_ref()
                                .is_some_and(|(_, raw, prefixes)| {
                                    typed_numbering_leaf_has_unmodeled(raw, prefixes)
                                })
                            || definition.levels.iter().any(|level| {
                                numbering_level_has_unmodeled(level)
                                    || matches!(
                                        level.num_fmt.as_ref(),
                                        Some(ST_NumberFormat::Other(_))
                                    )
                            }),
                    })
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Inspect one abstract numbering definition by identifier.
    pub fn numbering_definition(&self, id: u32) -> Option<NumberingDefinition> {
        self.numbering_definitions()
            .into_iter()
            .find(|definition| definition.id == id)
    }

    /// Inspect all numbering instances in package order.
    pub fn numbering_instances(&self) -> Vec<NumberingInstance> {
        self.numbering
            .as_ref()
            .map(|numbering| {
                numbering
                    .nums
                    .iter()
                    .map(|instance| NumberingInstance {
                        id: instance.num_id,
                        definition_id: instance.abstract_num_id,
                        level_overrides: instance
                            .level_overrides
                            .iter()
                            .map(|value| NumberingLevelOverride {
                                level: value.ilvl,
                                start: value.start_override,
                                replacement: value.level.as_ref().map(list_level_from_ct),
                                paragraph_style_link: value
                                    .level
                                    .as_ref()
                                    .and_then(|level| level.p_style.clone()),
                                has_unmodeled_properties: numbering_override_has_unmodeled(value),
                            })
                            .collect(),
                        has_unmodeled_properties: !instance.extra_xml.is_empty()
                            || !instance.extra_attributes.is_empty()
                            || instance.abstract_num_id_raw.as_ref().is_some_and(
                                |(_, raw, prefixes)| {
                                    typed_numbering_leaf_has_unmodeled(raw, prefixes)
                                },
                            )
                            || instance
                                .level_overrides
                                .iter()
                                .any(numbering_override_has_unmodeled),
                    })
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Inspect one numbering instance by identifier.
    pub fn numbering_instance(&self, id: u32) -> Option<NumberingInstance> {
        self.numbering_instances()
            .into_iter()
            .find(|instance| instance.id == id)
    }

    /// Create an abstract numbering definition and return its identifier.
    pub fn add_numbering_definition(&mut self, levels: &[ListLevel]) -> Result<u32> {
        validate_numbering_level_slice(levels)?;
        let authored = levels
            .iter()
            .enumerate()
            .map(|(level, value)| ct_level_from_list(level as u32, value))
            .collect::<Result<Vec<_>>>()?;
        let mut candidate = self.clone_for_staging();
        candidate.reserve_numbering_bundle()?;
        let id = candidate.identifiers.reserve_abstract_numbering_id()?;
        let mut definition = CT_AbstractNum::new(id);
        definition.multi_level_type = Some("hybridMultilevel".to_owned());
        definition.levels = authored;
        candidate.ensure_numbering().push_abstract_num(definition);
        candidate.validate_numbering_graph()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(id)
    }

    /// Replace the modeled levels of an existing abstract definition.
    pub fn update_numbering_definition(
        &mut self,
        id: u32,
        levels: &[NumberingDefinitionLevel],
    ) -> Result<()> {
        validate_numbering_definition_levels(levels)?;
        let mut candidate = self.clone_for_staging();
        let numbering = candidate
            .numbering
            .as_mut()
            .ok_or_else(|| Error::Other(format!("numbering definition {id} does not exist")))?;
        let definition = numbering
            .abstract_nums
            .iter_mut()
            .find(|definition| definition.abstract_num_id == id)
            .ok_or_else(|| Error::Other(format!("numbering definition {id} does not exist")))?;
        if definition.levels.len() != levels.len() {
            return Err(Error::Other(format!(
                "numbering definition {id} updates must retain its {} levels",
                definition.levels.len()
            )));
        }
        definition.levels = definition
            .levels
            .iter()
            .map(|existing| {
                let value = levels
                    .iter()
                    .find(|value| value.level == existing.ilvl)
                    .ok_or_else(|| {
                        Error::Other(format!(
                            "numbering definition {id} update is missing level {}",
                            existing.ilvl
                        ))
                    })?;
                merge_list_level(existing, &value.properties)
            })
            .collect::<Result<Vec<_>>>()?;
        candidate.reserve_numbering_bundle()?;
        candidate.validate_numbering_graph()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// Remove an abstract definition that no instance references.
    pub fn remove_numbering_definition(&mut self, id: u32) -> Result<bool> {
        let Some(numbering) = self.numbering.as_ref() else {
            return Ok(false);
        };
        if !numbering
            .abstract_nums
            .iter()
            .any(|definition| definition.abstract_num_id == id)
        {
            return Ok(false);
        }
        if let Some(instance) = numbering
            .nums
            .iter()
            .find(|instance| instance.abstract_num_id == id)
        {
            return Err(Error::Other(format!(
                "numbering definition {id} is referenced by instance {}",
                instance.num_id
            )));
        }
        let mut candidate = self.clone_for_staging();
        candidate
            .numbering
            .as_mut()
            .expect("checked numbering part")
            .remove_abstract_num(id);
        candidate.validate_numbering_graph()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(true)
    }

    /// Create a numbering instance for an existing definition.
    pub fn add_numbering_instance(
        &mut self,
        definition_id: u32,
        overrides: &[NumberingLevelOverride],
    ) -> Result<u32> {
        let mut candidate = self.clone_for_staging();
        candidate.reserve_numbering_bundle()?;
        let numbering = candidate.ensure_numbering();
        if !numbering
            .abstract_nums
            .iter()
            .any(|definition| definition.abstract_num_id == definition_id)
        {
            return Err(Error::Other(format!(
                "numbering definition {definition_id} does not exist"
            )));
        }
        let level_overrides = overrides
            .iter()
            .map(numbering_override_from_public)
            .collect::<Result<Vec<_>>>()?;
        let id = candidate.identifiers.reserve_numbering_instance_id()?;
        candidate.ensure_numbering().push_num(CT_Num {
            num_id: id,
            abstract_num_id: definition_id,
            abstract_num_id_raw: None,
            level_overrides,
            extra_xml: Vec::new(),
            extra_attributes: Vec::new(),
        });
        candidate.validate_numbering_graph()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(id)
    }

    /// Replace the definition and overrides used by an existing instance.
    pub fn update_numbering_instance(
        &mut self,
        id: u32,
        definition_id: u32,
        overrides: &[NumberingLevelOverride],
    ) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        let numbering = candidate
            .numbering
            .as_mut()
            .ok_or_else(|| Error::Other(format!("numbering instance {id} does not exist")))?;
        if !numbering
            .abstract_nums
            .iter()
            .any(|definition| definition.abstract_num_id == definition_id)
        {
            return Err(Error::Other(format!(
                "numbering definition {definition_id} does not exist"
            )));
        }
        let instance = numbering
            .nums
            .iter_mut()
            .find(|instance| instance.num_id == id)
            .ok_or_else(|| Error::Other(format!("numbering instance {id} does not exist")))?;
        let mut updated = Vec::with_capacity(overrides.len());
        for value in overrides {
            let existing = instance
                .level_overrides
                .iter()
                .find(|existing| existing.ilvl == value.level);
            updated.push(numbering_override_for_update(existing, value)?);
        }
        instance.abstract_num_id = definition_id;
        instance.level_overrides = updated;
        candidate.reserve_numbering_bundle()?;
        candidate.validate_numbering_graph()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// Remove an unreferenced numbering instance.
    pub fn remove_numbering_instance(&mut self, id: u32) -> Result<bool> {
        let Some(numbering) = self.numbering.as_ref() else {
            return Ok(false);
        };
        if !numbering.nums.iter().any(|instance| instance.num_id == id) {
            return Ok(false);
        }
        if self.document_references_numbering_instance(id)? {
            return Err(Error::Other(format!(
                "numbering instance {id} is referenced by document content"
            )));
        }
        let mut candidate = self.clone_for_staging();
        candidate
            .numbering
            .as_mut()
            .expect("checked numbering part")
            .remove_num(id);
        candidate.validate_numbering_graph()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(true)
    }

    /// Validate the complete typed numbering graph.
    pub fn validate_numbering_graph(&self) -> Result<()> {
        let numbering = self.numbering.as_ref();
        let Some(numbering) = numbering else {
            for style in &self.styles.styles {
                if style.style_type == StyleType::Paragraph
                    && style
                        .ppr
                        .as_ref()
                        .and_then(|properties| properties.num_id)
                        .is_some_and(|num_id| num_id != 0)
                {
                    return Err(Error::Other(format!(
                        "style '{}' references a missing numbering part",
                        style.style_id
                    )));
                }
            }
            let live_references = self.document_numbering_references()?;
            if let Some((num_id, level)) = live_references.first() {
                return Err(Error::Other(format!(
                    "document content references missing numbering instance {num_id} at level {level}"
                )));
            }
            return Ok(());
        };
        let mut definition_ids = HashSet::new();
        for definition in &numbering.abstract_nums {
            if !definition_ids.insert(definition.abstract_num_id) {
                return Err(Error::Other(format!(
                    "duplicate numbering definition id {}",
                    definition.abstract_num_id
                )));
            }
            let mut levels = HashSet::new();
            for level in &definition.levels {
                if level.ilvl > 8 || !levels.insert(level.ilvl) {
                    return Err(Error::Other(format!(
                        "numbering definition {} has invalid or duplicate level {}",
                        definition.abstract_num_id, level.ilvl
                    )));
                }
                validate_ct_numbering_level(level)?;
                if let Some(style_id) = level.p_style.as_deref()
                    && self.styles.get_by_id(style_id).is_none()
                {
                    return Err(Error::Other(format!(
                        "numbering definition {} references missing style '{style_id}'",
                        definition.abstract_num_id
                    )));
                }
            }
        }
        let mut instance_ids = HashSet::new();
        for instance in &numbering.nums {
            if instance.num_id == 0 || !instance_ids.insert(instance.num_id) {
                return Err(Error::Other(format!(
                    "invalid or duplicate numbering instance id {}",
                    instance.num_id
                )));
            }
            let definition = numbering
                .abstract_nums
                .iter()
                .find(|definition| definition.abstract_num_id == instance.abstract_num_id)
                .ok_or_else(|| {
                    Error::Other(format!(
                        "numbering instance {} references missing definition {}",
                        instance.num_id, instance.abstract_num_id
                    ))
                })?;
            let mut override_levels = HashSet::new();
            for level_override in &instance.level_overrides {
                if level_override.ilvl > 8 || !override_levels.insert(level_override.ilvl) {
                    return Err(Error::Other(format!(
                        "numbering instance {} has invalid or duplicate override level {}",
                        instance.num_id, level_override.ilvl
                    )));
                }
                if !definition
                    .levels
                    .iter()
                    .any(|level| level.ilvl == level_override.ilvl)
                {
                    return Err(Error::Other(format!(
                        "numbering instance {} override level {} is not owned by definition {}",
                        instance.num_id, level_override.ilvl, instance.abstract_num_id
                    )));
                }
                if let Some(level) = &level_override.level {
                    if level.ilvl != level_override.ilvl {
                        return Err(Error::Other(format!(
                            "numbering instance {} override level {} owns replacement level {}",
                            instance.num_id, level_override.ilvl, level.ilvl
                        )));
                    }
                    validate_ct_numbering_level(level)?;
                    if let Some(style_id) = level.p_style.as_deref()
                        && self.styles.get_by_id(style_id).is_none()
                    {
                        return Err(Error::Other(format!(
                            "numbering instance {} override references missing style '{style_id}'",
                            instance.num_id
                        )));
                    }
                }
            }
        }
        let mut style_links = HashMap::<&str, (u32, u32)>::new();
        for style in &self.styles.styles {
            if style.style_type != StyleType::Paragraph {
                continue;
            }
            let Some(properties) = style.ppr.as_ref() else {
                continue;
            };
            // A `w:ilvl` without a `w:numId` is schema-valid. The style takes
            // the instance of its `basedOn` chain, as layout and Word resolve
            // it, and is not numbered when the chain has none. It owns no link
            // of its own, so only a level that names it back records one.
            let (num_id, inherited) = match properties.num_id {
                Some(num_id) => (num_id, false),
                None if properties.num_ilvl.is_some() => {
                    match style::resolve_paragraph_properties(Some(&style.style_id), &self.styles)
                        .num_id
                    {
                        Some(num_id) => (num_id, true),
                        None => continue,
                    }
                }
                None => continue,
            };
            if num_id == 0 {
                continue;
            }
            let level = properties.num_ilvl.unwrap_or(0);
            let instance = numbering
                .nums
                .iter()
                .find(|instance| instance.num_id == num_id)
                .ok_or_else(|| {
                    Error::Other(format!(
                        "style '{}' references missing numbering instance {num_id}",
                        style.style_id
                    ))
                })?;
            let definition = numbering
                .abstract_nums
                .iter()
                .find(|definition| definition.abstract_num_id == instance.abstract_num_id)
                .expect("numbering instances were validated above");
            let base = definition
                .levels
                .iter()
                .find(|candidate| candidate.ilvl == level)
                .ok_or_else(|| {
                    Error::Other(format!(
                        "style '{}' references numbering instance {num_id} at missing level {level}",
                        style.style_id
                    ))
                })?;
            let effective = instance
                .level_overrides
                .iter()
                .find(|value| value.ilvl == level)
                .and_then(|value| value.level.as_ref())
                .unwrap_or(base);
            if effective.p_style.as_deref() != Some(style.style_id.as_str()) {
                if inherited {
                    continue;
                }
                return Err(Error::Other(format!(
                    "style '{}' and numbering instance {num_id} level {level} are not reciprocally linked",
                    style.style_id
                )));
            }
            style_links.insert(style.style_id.as_str(), (num_id, level));
        }
        for definition in &numbering.abstract_nums {
            for level in &definition.levels {
                let Some(style_id) = level.p_style.as_deref() else {
                    continue;
                };
                let linked = style_links.get(style_id).is_some_and(|(num_id, ilvl)| {
                    *ilvl == level.ilvl
                        && numbering.nums.iter().any(|instance| {
                            instance.num_id == *num_id
                                && instance.abstract_num_id == definition.abstract_num_id
                        })
                });
                if !linked {
                    return Err(Error::Other(format!(
                        "numbering definition {} level {} and style '{style_id}' are not reciprocally linked",
                        definition.abstract_num_id, level.ilvl
                    )));
                }
            }
        }
        for instance in &numbering.nums {
            for level in instance
                .level_overrides
                .iter()
                .filter_map(|value| value.level.as_ref())
            {
                let Some(style_id) = level.p_style.as_deref() else {
                    continue;
                };
                if style_links.get(style_id) != Some(&(instance.num_id, level.ilvl)) {
                    return Err(Error::Other(format!(
                        "numbering instance {} replacement level {} and style '{style_id}' are not reciprocally linked",
                        instance.num_id, level.ilvl
                    )));
                }
            }
        }
        let live_references = self.document_numbering_references()?;
        for (num_id, level) in live_references {
            let instance = numbering
                .nums
                .iter()
                .find(|instance| instance.num_id == num_id)
                .ok_or_else(|| {
                    Error::Other(format!(
                        "document content references missing numbering instance {num_id} at level {level}"
                    ))
                })?;
            let definition = numbering
                .abstract_nums
                .iter()
                .find(|definition| definition.abstract_num_id == instance.abstract_num_id)
                .expect("numbering instances were validated above");
            if !definition
                .levels
                .iter()
                .any(|candidate| candidate.ilvl == level)
            {
                return Err(Error::Other(format!(
                    "document content references numbering instance {num_id} at missing level {level}"
                )));
            }
        }
        Ok(())
    }

    fn document_numbering_references(&self) -> Result<Vec<(u32, u32)>> {
        let mut candidate = self.clone_for_staging();
        candidate.flush_to_package()?;
        let mut references = Vec::new();
        for part_name in candidate.word_story_part_names() {
            let Some(xml) = candidate.package.get_part(&part_name) else {
                continue;
            };
            // A main part a flush wrote from the kept blocks is read in them.
            let by_blocks = (part_name == candidate.doc_part_name)
                .then(|| candidate.main_part_blocks())
                .flatten()
                .and_then(|blocks| blocks.numbering(xml));
            let properties = match by_blocks {
                Some(properties) => properties,
                None if identifier_xml_is_well_formed(xml) => {
                    xml_paragraph_numbering_properties(xml)?
                }
                None => continue,
            };
            for direct in properties {
                let style_id = direct.style_id.as_deref().or_else(|| {
                    candidate
                        .styles
                        .get_default(StyleType::Paragraph)
                        .map(|style| style.style_id.as_str())
                });
                let mut effective =
                    style::resolve_paragraph_properties(style_id, &candidate.styles);
                candidate.apply_effective_numbering(&mut effective, Some(&direct), style_id);
                if let Some(num_id) = effective.num_id
                    && num_id != 0
                {
                    references.push((num_id, effective.num_ilvl.unwrap_or(0)));
                }
            }
        }
        Ok(references)
    }

    pub(crate) fn word_story_part_names(&self) -> Vec<String> {
        let mut story_parts = vec![self.doc_part_name.clone()];
        if let Some(relationships) = self.package.get_part_rels(&self.doc_part_name) {
            story_parts.extend(
                relationships
                    .items
                    .iter()
                    .filter(|relationship| {
                        relationship_is_internal(relationship)
                            && matches!(
                                relationship.rel_type.as_str(),
                                rel_types::HEADER
                                    | rel_types::FOOTER
                                    | rel_types::FOOTNOTES
                                    | rel_types::ENDNOTES
                                    | rel_types::COMMENTS
                                    | rel_types::GLOSSARY_DOCUMENT
                            )
                    })
                    .map(|relationship| {
                        OpcPackage::resolve_rel_target(&self.doc_part_name, &relationship.target)
                    }),
            );
        }
        story_parts
    }

    fn document_references_numbering_instance(&self, id: u32) -> Result<bool> {
        let mut candidate = self.clone_for_staging();
        candidate.flush_to_package()?;
        let mut owners = candidate.word_story_part_names();
        owners.extend(candidate.styles_part_name.clone());
        for xml in owners.into_iter().filter_map(|part_name| {
            candidate
                .package
                .get_part(&part_name)
                .filter(|bytes| identifier_xml_is_well_formed(bytes))
        }) {
            if xml_references_numbering_instance(xml, id)? {
                return Ok(true);
            }
        }
        Ok(false)
    }

    /// Redefine one level (0–8) of an existing list definition, for callers
    /// that only learn a deeper level's format when content first reaches it.
    ///
    /// Returns `false` when `num_id` is unknown or `level` is out of range.
    pub fn set_list_level(&mut self, num_id: u32, level: u32, spec: ListLevel) -> bool {
        if validate_list_level(level, &spec).is_err() {
            return false;
        }
        let mut candidate = self.clone_for_staging();
        let updated = candidate.numbering.as_mut().is_some_and(|numbering| {
            let Some(abstract_id) = numbering
                .nums
                .iter()
                .find(|instance| instance.num_id == num_id)
                .map(|instance| instance.abstract_num_id)
            else {
                return false;
            };
            let Some(definition) = numbering
                .abstract_nums
                .iter_mut()
                .find(|definition| definition.abstract_num_id == abstract_id)
            else {
                return false;
            };
            let Some(index) = definition
                .levels
                .iter()
                .position(|existing| existing.ilvl == level)
            else {
                return false;
            };
            let Ok(updated) = merge_list_level(&definition.levels[index], &spec) else {
                return false;
            };
            definition.levels[index] = updated;
            true
        });
        if updated {
            candidate
                .reserve_numbering_bundle()
                .expect("an in-memory document can allocate a numbering part");
            if candidate.validate_numbering_graph().is_err() {
                return false;
            }
            candidate.invalidate_layout();
            self.commit_staged_mutation(candidate);
        }
        updated
    }

    /// Atomically associate a paragraph style with one concrete numbering level.
    ///
    /// Both the style's paragraph properties and the numbering level's
    /// paragraph-style link are published together. Existing links must either
    /// match this exact tuple or the operation fails without changing the
    /// document. A style `w:numPr` holding a `w:ilvl` and no `w:numId` is not
    /// a link, and the new link replaces its level. A repeated style ID
    /// resolves to its first definition, and the style graph is validated as
    /// in [`Document::add_style`].
    pub fn link_style_to_numbering(
        &mut self,
        style_id: &str,
        num_id: u32,
        level: u32,
    ) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.validate_numbering_graph()?;
        candidate.reserve_styles_bundle()?;
        candidate.reserve_numbering_bundle()?;

        let style_index = candidate
            .styles
            .styles
            .iter()
            .position(|style| style.style_id == style_id)
            .ok_or_else(|| Error::Other(format!("style '{style_id}' does not exist")))?;
        if candidate.styles.styles[style_index].style_type != StyleType::Paragraph {
            return Err(Error::Other(format!(
                "style '{style_id}' is not a paragraph style"
            )));
        }

        let numbering = candidate
            .numbering
            .as_ref()
            .ok_or_else(|| Error::Other(format!("numbering instance {num_id} does not exist")))?;
        let instance_index = numbering
            .nums
            .iter()
            .position(|instance| instance.num_id == num_id)
            .ok_or_else(|| Error::Other(format!("numbering instance {num_id} does not exist")))?;
        let definition_id = numbering.nums[instance_index].abstract_num_id;
        let definition_index = numbering
            .abstract_nums
            .iter()
            .position(|definition| definition.abstract_num_id == definition_id)
            .expect("the numbering graph was validated");
        let override_index = numbering.nums[instance_index]
            .level_overrides
            .iter()
            .position(|value| value.ilvl == level && value.level.is_some());
        let definition_level_index = numbering.abstract_nums[definition_index]
            .levels
            .iter()
            .position(|value| value.ilvl == level)
            .ok_or_else(|| {
                Error::Other(format!("numbering instance {num_id} has no level {level}"))
            })?;

        let style_numbering = candidate.styles.styles[style_index]
            .ppr
            .as_ref()
            .map(|properties| (properties.num_id, properties.num_ilvl))
            .unwrap_or((None, None));
        // A `w:ilvl` without a `w:numId` owns no link, so the link replaces it.
        if style_numbering.0.is_some() && style_numbering != (Some(num_id), Some(level)) {
            return Err(Error::Other(format!(
                "style '{style_id}' already references a different numbering level"
            )));
        }

        for (candidate_definition_index, definition) in numbering.abstract_nums.iter().enumerate() {
            for (candidate_level_index, candidate_level) in definition.levels.iter().enumerate() {
                if candidate_level.p_style.as_deref() == Some(style_id)
                    && (candidate_definition_index, candidate_level_index)
                        != (definition_index, definition_level_index)
                {
                    return Err(Error::Other(format!(
                        "style '{style_id}' is already linked to another numbering level"
                    )));
                }
            }
        }
        for (candidate_instance_index, instance) in numbering.nums.iter().enumerate() {
            for (candidate_override_index, value) in instance.level_overrides.iter().enumerate() {
                if value
                    .level
                    .as_ref()
                    .and_then(|level| level.p_style.as_deref())
                    == Some(style_id)
                    && Some(candidate_override_index)
                        != override_index.filter(|_| candidate_instance_index == instance_index)
                {
                    return Err(Error::Other(format!(
                        "style '{style_id}' is already linked to another numbering level"
                    )));
                }
            }
        }

        let target_style = override_index
            .and_then(|index| {
                numbering.nums[instance_index].level_overrides[index]
                    .level
                    .as_ref()
            })
            .unwrap_or(&numbering.abstract_nums[definition_index].levels[definition_level_index])
            .p_style
            .as_deref();
        if target_style.is_some() && target_style != Some(style_id) {
            return Err(Error::Other(format!(
                "numbering instance {num_id} level {level} is already linked to another style"
            )));
        }

        let properties = candidate.styles.styles[style_index]
            .ppr
            .get_or_insert_with(CT_PPr::default);
        properties.num_id = Some(num_id);
        properties.num_ilvl = Some(level);
        let numbering = candidate
            .numbering
            .as_mut()
            .expect("the numbering part was resolved above");
        if let Some(index) = override_index {
            numbering.nums[instance_index].level_overrides[index]
                .level
                .as_mut()
                .expect("the override was selected only when it owns a level")
                .p_style = Some(style_id.to_owned());
        } else {
            numbering.abstract_nums[definition_index].levels[definition_level_index].p_style =
                Some(style_id.to_owned());
        }

        style::validate_style_graph_change(&self.styles, &candidate.styles)?;
        candidate.validate_numbering_graph()?;
        candidate.flush_to_package()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// Atomically remove one exact paragraph-style numbering association.
    ///
    /// Unlinking removes the style's `w:numId` and `w:ilvl` together, so a
    /// style that held only a `w:ilvl` before it was linked does not get it
    /// back. A style that holds only a `w:ilvl`, takes its instance from its
    /// `basedOn` chain and is named back by the level loses only that name
    /// and keeps its level. A style holding only a `w:ilvl` that no level
    /// names is not linked, and unlinking it changes nothing. A repeated
    /// style ID resolves to its first definition, and the style graph is
    /// validated as in [`Document::add_style`].
    pub fn unlink_style_from_numbering(
        &mut self,
        style_id: &str,
        num_id: u32,
        level: u32,
    ) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.validate_numbering_graph()?;

        let style_index = candidate
            .styles
            .styles
            .iter()
            .position(|style| style.style_id == style_id)
            .ok_or_else(|| Error::Other(format!("style '{style_id}' does not exist")))?;
        if candidate.styles.styles[style_index].style_type != StyleType::Paragraph {
            return Err(Error::Other(format!(
                "style '{style_id}' is not a paragraph style"
            )));
        }
        let numbering = candidate
            .numbering
            .as_ref()
            .ok_or_else(|| Error::Other(format!("numbering instance {num_id} does not exist")))?;
        let instance_index = numbering
            .nums
            .iter()
            .position(|instance| instance.num_id == num_id)
            .ok_or_else(|| Error::Other(format!("numbering instance {num_id} does not exist")))?;
        let definition_id = numbering.nums[instance_index].abstract_num_id;
        let definition_index = numbering
            .abstract_nums
            .iter()
            .position(|definition| definition.abstract_num_id == definition_id)
            .expect("the numbering graph was validated");
        let override_index = numbering.nums[instance_index]
            .level_overrides
            .iter()
            .position(|value| value.ilvl == level && value.level.is_some());
        let definition_level_index = numbering.abstract_nums[definition_index]
            .levels
            .iter()
            .position(|value| value.ilvl == level)
            .ok_or_else(|| {
                Error::Other(format!("numbering instance {num_id} has no level {level}"))
            })?;

        let style_numbering = candidate.styles.styles[style_index]
            .ppr
            .as_ref()
            .map(|properties| (properties.num_id, properties.num_ilvl))
            .unwrap_or((None, None));
        let target_style = override_index
            .and_then(|index| {
                numbering.nums[instance_index].level_overrides[index]
                    .level
                    .as_ref()
            })
            .unwrap_or(&numbering.abstract_nums[definition_index].levels[definition_level_index])
            .p_style
            .as_deref();
        if style_numbering.0.is_none() && target_style.is_none() {
            return Ok(());
        }
        // A level may name back a style that takes its instance from its
        // `basedOn` chain, which is the link recorded for it.
        let inherited = style_numbering == (None, Some(level))
            && style::resolve_paragraph_properties(Some(style_id), &candidate.styles).num_id
                == Some(num_id);
        if (style_numbering != (Some(num_id), Some(level)) && !inherited)
            || target_style != Some(style_id)
        {
            return Err(Error::Other(format!(
                "style '{style_id}' and numbering instance {num_id} level {level} are not linked"
            )));
        }

        candidate.reserve_styles_bundle()?;
        candidate.reserve_numbering_bundle()?;
        let properties = candidate.styles.styles[style_index]
            .ppr
            .as_mut()
            .expect("the exact style link was validated above");
        if !inherited {
            properties.num_id = None;
            properties.num_ilvl = None;
        }
        let numbering = candidate
            .numbering
            .as_mut()
            .expect("the numbering part was resolved above");
        if let Some(index) = override_index {
            numbering.nums[instance_index].level_overrides[index]
                .level
                .as_mut()
                .expect("the override was selected only when it owns a level")
                .p_style = None;
        } else {
            numbering.abstract_nums[definition_index].levels[definition_level_index].p_style = None;
        }

        style::validate_style_graph_change(&self.styles, &candidate.styles)?;
        candidate.validate_numbering_graph()?;
        candidate.flush_to_package()?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    // ---- Style access ----

    /// Get all styles.
    pub fn styles(&self) -> Vec<Style<'_>> {
        self.styles
            .styles
            .iter()
            .map(|s| Style { inner: s })
            .collect()
    }

    /// Find a style by its ID.
    pub fn style(&self, style_id: &str) -> Option<Style<'_>> {
        self.styles.get_by_id(style_id).map(|s| Style { inner: s })
    }

    // ---- Style manipulation ----

    /// Add a custom style after validating the change to the style graph.
    ///
    /// A defect the styles part already has, such as a style ID a producer
    /// repeated, is retained, and [`Document::validate_style_graph`] still
    /// reports it. Only a defect the change introduces rejects it, and an ID
    /// that already exists is refused. The style mutations resolve a repeated
    /// ID to its first definition, as layout and TOC rebuilding do.
    pub fn add_style(&mut self, builder: StyleBuilder) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        let (authored, _, _) = builder.build();
        if candidate.styles.get_by_id(&authored.style_id).is_some() {
            return Err(Error::Other(format!(
                "style '{}' already exists",
                authored.style_id
            )));
        }
        if authored
            .ppr
            .as_ref()
            .is_some_and(|properties| properties.num_id.is_some() || properties.num_ilvl.is_some())
        {
            return Err(Error::Other(format!(
                "style '{}' numbering must be established with link_style_to_numbering",
                authored.style_id
            )));
        }
        let linked_style = authored.linked_style.clone();
        let style_id = authored.style_id.clone();
        candidate.styles.styles.push(authored);
        update_reciprocal_style_link(
            &mut candidate.styles,
            &style_id,
            None,
            linked_style.as_deref(),
        );
        style::validate_style_graph_change(&self.styles, &candidate.styles)?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// Replace an existing style after validating the change to the style graph.
    ///
    /// A repeated style ID updates its first definition. Validation retains
    /// existing defects as in [`Document::add_style`].
    pub fn set_style(&mut self, builder: StyleBuilder) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        let (mut authored, cleared, removed_regions) = builder.build();
        let index = candidate
            .styles
            .styles
            .iter()
            .position(|style| style.style_id == authored.style_id)
            .ok_or_else(|| Error::Other(format!("style '{}' does not exist", authored.style_id)))?;
        let existing = &candidate.styles.styles[index];
        if existing.style_type != authored.style_type {
            return Err(Error::Other(format!(
                "style '{}' has type '{}', not '{}'",
                authored.style_id,
                existing.style_type.to_str(),
                authored.style_type.to_str()
            )));
        }
        let old_link = existing.linked_style.clone();
        merge_style_update(existing, &mut authored, cleared, &removed_regions);
        let existing_numbering = existing
            .ppr
            .as_ref()
            .map(|properties| (properties.num_id, properties.num_ilvl))
            .unwrap_or((None, None));
        let authored_numbering = authored
            .ppr
            .as_ref()
            .map(|properties| (properties.num_id, properties.num_ilvl))
            .unwrap_or((None, None));
        if authored_numbering != existing_numbering {
            return Err(Error::Other(format!(
                "style '{}' numbering must be changed with link_style_to_numbering or unlink_style_from_numbering",
                authored.style_id
            )));
        }
        let style_id = authored.style_id.clone();
        let new_link = authored.linked_style.clone();
        candidate.styles.styles[index] = authored;
        update_reciprocal_style_link(
            &mut candidate.styles,
            &style_id,
            old_link.as_deref(),
            new_link.as_deref(),
        );
        style::validate_style_graph_change(&self.styles, &candidate.styles)?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// Select the sole default style for one style type.
    ///
    /// A repeated style ID makes its first definition the default. Validation
    /// retains existing defects as in [`Document::add_style`].
    pub fn set_default_style(&mut self, style_type: StyleType, style_id: &str) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        let index = candidate
            .styles
            .styles
            .iter()
            .position(|style| style.style_id == style_id)
            .ok_or_else(|| Error::Other(format!("style '{style_id}' does not exist")))?;
        let target = &candidate.styles.styles[index];
        if target.style_type != style_type {
            return Err(Error::Other(format!(
                "style '{style_id}' has type '{}', not '{}'",
                target.style_type.to_str(),
                style_type.to_str()
            )));
        }
        for (position, style) in candidate.styles.styles.iter_mut().enumerate() {
            if style.style_type == style_type {
                style.is_default = position == index;
            }
        }
        style::validate_style_graph_change(&self.styles, &candidate.styles)?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(())
    }

    /// Remove an unreferenced style, returning whether it existed.
    ///
    /// Every definition of a repeated style ID is removed, so no later one takes
    /// over the ID. Validation retains existing defects as in
    /// [`Document::add_style`].
    pub fn remove_style(&mut self, style_id: &str) -> Result<bool> {
        if self.styles.get_by_id(style_id).is_none() {
            return Ok(false);
        }
        if let Some(owner) = self.styles.styles.iter().find(|style| {
            style.style_id != style_id
                && (style.based_on.as_deref() == Some(style_id)
                    || style.next_style.as_deref() == Some(style_id)
                    || style.linked_style.as_deref() == Some(style_id))
        }) {
            return Err(Error::Other(format!(
                "style '{style_id}' is referenced by style '{}'",
                owner.style_id
            )));
        }
        if self.document_references_style(style_id)? {
            return Err(Error::Other(format!(
                "style '{style_id}' is referenced by document content"
            )));
        }
        if self.numbering.as_ref().is_some_and(|numbering| {
            numbering.abstract_nums.iter().any(|definition| {
                definition
                    .levels
                    .iter()
                    .any(|level| level.p_style.as_deref() == Some(style_id))
            }) || numbering.nums.iter().any(|instance| {
                instance.level_overrides.iter().any(|value| {
                    value
                        .level
                        .as_ref()
                        .is_some_and(|level| level.p_style.as_deref() == Some(style_id))
                })
            })
        }) {
            return Err(Error::Other(format!(
                "style '{style_id}' is referenced by a numbering level"
            )));
        }

        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        candidate
            .styles
            .styles
            .retain(|style| style.style_id != style_id);
        style::validate_style_graph_change(&self.styles, &candidate.styles)?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(true)
    }

    /// Add the Word built-in styles most documents use and python-docx's
    /// default template defines, returning how many were added.
    ///
    /// They are `heading 2` to `heading 9`, `Title`, `Subtitle`,
    /// `No Spacing`, `Quote`, `List Paragraph`, `caption` and `Table Grid`,
    /// none of them a default style, so content that names none of them lays
    /// out as before. A style whose ID, or whose name regardless of case, the
    /// document already defines is skipped. Most are based on `Normal`, so a
    /// document without a `Normal` paragraph style is rejected unchanged.
    pub fn add_common_styles(&mut self) -> Result<usize> {
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        let mut added = 0;
        for common in style::common_styles() {
            let defined = candidate.styles.styles.iter().any(|style| {
                style.style_id == common.style_id
                    || style
                        .name
                        .as_deref()
                        .zip(common.name.as_deref())
                        .is_some_and(|(name, common)| name.eq_ignore_ascii_case(common))
            });
            if !defined {
                candidate.styles.styles.push(common);
                added += 1;
            }
        }
        if added == 0 {
            return Ok(0);
        }
        style::validate_style_graph(&candidate.styles)?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(added)
    }

    /// Materialize the requested supported built-in table style, without changing defaults.
    pub fn ensure_builtin_table_style(&mut self, name: &str) -> Result<bool> {
        if !matches!(name, "LightShading-Accent1" | "Light Shading Accent 1") {
            return Ok(false);
        }
        if self.styles.styles.iter().any(|s| {
            s.style_id == "LightShading-Accent1"
                || s.name
                    .as_deref()
                    .is_some_and(|n| n.eq_ignore_ascii_case(name))
        }) {
            return Ok(false);
        }
        // python-docx 1.2.0 default.docx, SHA-256 2094b5bddffe9cf973d61fe03388413804f034160718494a65db7e98da40d35d.
        // The existing TableNormal base is retained. A copied absent base is nondefault.
        let definitions = CT_Styles::from_xml(br#"<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:style w:type="table" w:styleId="TableNormal">
    <w:name w:val="Normal Table"/>
    <w:uiPriority w:val="99"/>
    <w:semiHidden/>
    <w:unhideWhenUsed/>
    <w:tblPr>
      <w:tblInd w:w="0" w:type="dxa"/>
      <w:tblCellMar>
        <w:top w:w="0" w:type="dxa"/>
        <w:left w:w="108" w:type="dxa"/>
        <w:bottom w:w="0" w:type="dxa"/>
        <w:right w:w="108" w:type="dxa"/>
      </w:tblCellMar>
    </w:tblPr>
  </w:style><w:style w:type="table" w:styleId="LightShading-Accent1">
    <w:name w:val="Light Shading Accent 1"/>
    <w:basedOn w:val="TableNormal"/>
    <w:uiPriority w:val="60"/>
    <w:rsid w:val="00FC693F"/>
    <w:pPr>
      <w:spacing w:after="0" w:line="240" w:lineRule="auto"/>
    </w:pPr>
    <w:rPr>
      <w:color w:val="365F91" w:themeColor="accent1" w:themeShade="BF"/>
    </w:rPr>
    <w:tblPr>
      <w:tblStyleRowBandSize w:val="1"/>
      <w:tblStyleColBandSize w:val="1"/>
      <w:tblInd w:w="0" w:type="dxa"/>
      <w:tblBorders>
        <w:top w:val="single" w:sz="8" w:space="0" w:color="4F81BD" w:themeColor="accent1"/>
        <w:bottom w:val="single" w:sz="8" w:space="0" w:color="4F81BD" w:themeColor="accent1"/>
      </w:tblBorders>
      <w:tblCellMar>
        <w:top w:w="0" w:type="dxa"/>
        <w:left w:w="108" w:type="dxa"/>
        <w:bottom w:w="0" w:type="dxa"/>
        <w:right w:w="108" w:type="dxa"/>
      </w:tblCellMar>
    </w:tblPr>
    <w:tblStylePr w:type="firstRow">
      <w:pPr>
        <w:spacing w:before="0" w:after="0" w:line="240" w:lineRule="auto"/>
      </w:pPr>
      <w:rPr>
        <w:b/>
        <w:bCs/>
      </w:rPr>
      <w:tblPr/>
      <w:tcPr>
        <w:tcBorders>
          <w:top w:val="single" w:sz="8" w:space="0" w:color="4F81BD" w:themeColor="accent1"/>
          <w:left w:val="nil"/>
          <w:bottom w:val="single" w:sz="8" w:space="0" w:color="4F81BD" w:themeColor="accent1"/>
          <w:right w:val="nil"/>
          <w:insideH w:val="nil"/>
          <w:insideV w:val="nil"/>
        </w:tcBorders>
      </w:tcPr>
    </w:tblStylePr>
    <w:tblStylePr w:type="lastRow">
      <w:pPr>
        <w:spacing w:before="0" w:after="0" w:line="240" w:lineRule="auto"/>
      </w:pPr>
      <w:rPr>
        <w:b/>
        <w:bCs/>
      </w:rPr>
      <w:tblPr/>
      <w:tcPr>
        <w:tcBorders>
          <w:top w:val="single" w:sz="8" w:space="0" w:color="4F81BD" w:themeColor="accent1"/>
          <w:left w:val="nil"/>
          <w:bottom w:val="single" w:sz="8" w:space="0" w:color="4F81BD" w:themeColor="accent1"/>
          <w:right w:val="nil"/>
          <w:insideH w:val="nil"/>
          <w:insideV w:val="nil"/>
        </w:tcBorders>
      </w:tcPr>
    </w:tblStylePr>
    <w:tblStylePr w:type="firstCol">
      <w:rPr>
        <w:b/>
        <w:bCs/>
      </w:rPr>
    </w:tblStylePr>
    <w:tblStylePr w:type="lastCol">
      <w:rPr>
        <w:b/>
        <w:bCs/>
      </w:rPr>
    </w:tblStylePr>
    <w:tblStylePr w:type="band1Vert">
      <w:tblPr/>
      <w:tcPr>
        <w:tcBorders>
          <w:left w:val="nil"/>
          <w:right w:val="nil"/>
          <w:insideH w:val="nil"/>
          <w:insideV w:val="nil"/>
        </w:tcBorders>
        <w:shd w:val="clear" w:color="auto" w:fill="D3DFEE" w:themeFill="accent1" w:themeFillTint="3F"/>
      </w:tcPr>
    </w:tblStylePr>
    <w:tblStylePr w:type="band1Horz">
      <w:tblPr/>
      <w:tcPr>
        <w:tcBorders>
          <w:left w:val="nil"/>
          <w:right w:val="nil"/>
          <w:insideH w:val="nil"/>
          <w:insideV w:val="nil"/>
        </w:tcBorders>
        <w:shd w:val="clear" w:color="auto" w:fill="D3DFEE" w:themeFill="accent1" w:themeFillTint="3F"/>
      </w:tcPr>
    </w:tblStylePr>
  </w:style></w:styles>"#)?;
        let mut candidate = self.clone_for_staging();
        candidate.reserve_styles_bundle()?;
        for definition in definitions.styles {
            if let Some(existing) = candidate
                .styles
                .styles
                .iter()
                .find(|s| s.style_id == definition.style_id)
            {
                if existing.style_type != definition.style_type {
                    return Err(Error::Other(
                        "built-in table style base has a conflicting type".into(),
                    ));
                }
            } else {
                candidate.styles.styles.push(definition);
            }
        }
        style::validate_style_graph(&candidate.styles)?;
        candidate.invalidate_layout();
        self.commit_staged_mutation(candidate);
        Ok(true)
    }

    /// Validate all style IDs, defaults, links, next styles, and inheritance chains.
    pub fn validate_style_graph(&self) -> Result<()> {
        style::validate_style_graph(&self.styles)
    }

    fn document_references_style(&self, style_id: &str) -> Result<bool> {
        if body_references_style(&self.document.body.content, style_id)
            || xml_references_style(&self.document.to_xml()?, style_id)?
            || self
                .footnotes
                .footnotes
                .iter()
                .flat_map(|note| &note.paragraphs)
                .any(|paragraph| paragraph_references_style(paragraph, style_id))
            || self.comments.as_ref().is_some_and(|comments| {
                comments
                    .comments
                    .iter()
                    .flat_map(|comment| &comment.paragraphs)
                    .any(|paragraph| paragraph_references_style(paragraph, style_id))
            })
            || self.glossary.as_ref().is_some_and(|glossary| {
                glossary
                    .doc_parts
                    .iter()
                    .any(|part| body_references_style(&part.body.content, style_id))
            })
        {
            return Ok(true);
        }

        let Some(relationships) = self.package.get_part_rels(&self.doc_part_name) else {
            return Ok(false);
        };
        for relationship in &relationships.items {
            if relationship_is_internal(relationship)
                && matches!(
                    relationship.rel_type.as_str(),
                    rel_types::HEADER
                        | rel_types::FOOTER
                        | rel_types::FOOTNOTES
                        | rel_types::ENDNOTES
                        | rel_types::COMMENTS
                        | rel_types::GLOSSARY_DOCUMENT
                )
            {
                let part_name =
                    OpcPackage::resolve_rel_target(&self.doc_part_name, &relationship.target);
                if let Some(xml) = self.package.get_part(&part_name)
                    && xml_references_style(xml, style_id)?
                {
                    return Ok(true);
                }
            }
        }
        Ok(false)
    }

    /// Resolve the effective paragraph properties for a given style ID,
    /// walking the full inheritance chain (docDefaults → basedOn → ...).
    pub fn resolve_paragraph_properties(&self, style_id: Option<&str>) -> CT_PPr {
        style::resolve_paragraph_properties(style_id, &self.styles)
    }

    /// Resolve inherited, numbering-level, and direct properties for a
    /// concrete paragraph.
    pub fn effective_paragraph_properties(&self, paragraph: &ParagraphRef<'_>) -> CT_PPr {
        let direct = paragraph.inner.properties.as_ref();
        let style_id = direct
            .and_then(|properties| properties.style_id.as_deref())
            .or_else(|| {
                self.styles
                    .get_default(StyleType::Paragraph)
                    .map(|style| style.style_id.as_str())
            });
        let mut effective = style::resolve_paragraph_properties(style_id, &self.styles);
        self.apply_effective_numbering(&mut effective, direct, style_id);

        if let Some((num_id, level)) = effective.num_id.zip(effective.num_ilvl)
            && let Some(definition) = self.resolved_numbering_level_definition(num_id, level)
            && let Some(properties) = &definition.ppr
        {
            effective.merge_from(properties);
        }
        if let Some(properties) = direct {
            effective.merge_from(properties);
        }
        effective
    }

    fn apply_effective_numbering(
        &self,
        effective: &mut CT_PPr,
        direct: Option<&CT_PPr>,
        style_id: Option<&str>,
    ) {
        effective.num_id = direct
            .and_then(|properties| properties.num_id)
            .or(effective.num_id);
        effective.num_ilvl = direct
            .and_then(|properties| properties.num_ilvl)
            .or(effective.num_ilvl);
        if let Some(num_id) = effective.num_id {
            effective.num_ilvl = effective
                .num_ilvl
                .or_else(|| self.numbering_level_for_style(num_id, style_id));
        }
    }

    /// Resolve the effective run properties for the given paragraph and character styles,
    /// walking the full inheritance chain.
    pub fn resolve_run_properties(
        &self,
        para_style_id: Option<&str>,
        run_style_id: Option<&str>,
    ) -> CT_RPr {
        style::resolve_run_properties(para_style_id, run_style_id, &self.styles)
    }

    /// Resolve inherited, paragraph-mark, and direct properties for one
    /// concrete body run.
    pub fn effective_run_properties(
        &self,
        paragraph: &ParagraphRef<'_>,
        run: &RunRef<'_>,
    ) -> CT_RPr {
        self.effective_run_properties_from_direct(paragraph, run.inner.properties.as_ref())
    }

    /// Resolve inherited, paragraph-mark, and direct properties for one cached
    /// complex-field display segment.
    pub fn effective_field_segment_properties(
        &self,
        paragraph: &ParagraphRef<'_>,
        segment: &FieldDisplaySegmentRef<'_>,
    ) -> CT_RPr {
        self.effective_run_properties_from_direct(paragraph, segment.properties())
    }

    fn effective_run_properties_from_direct(
        &self,
        paragraph: &ParagraphRef<'_>,
        direct: Option<&CT_RPr>,
    ) -> CT_RPr {
        let paragraph_properties = paragraph.inner.properties.as_ref();
        let mut effective = style::resolve_run_properties(
            paragraph_properties.and_then(|properties| properties.style_id.as_deref()),
            direct.and_then(|properties| properties.style_id.as_deref()),
            &self.styles,
        );
        if let Some(properties) =
            paragraph_properties.and_then(|properties| properties.rpr.as_ref())
        {
            effective.merge_from(properties);
        }
        if let Some(properties) = direct {
            effective.merge_from(properties);
        }
        effective
    }

    fn resolved_numbering_level_definition(
        &self,
        num_id: u32,
        level: u32,
    ) -> Option<&rdocx_oxml::numbering::CT_Lvl> {
        if num_id == 0 {
            return None;
        }
        self.numbering
            .as_ref()?
            .get_abstract_num_for(num_id)?
            .levels
            .iter()
            .find(|definition| definition.ilvl == level)
    }

    fn numbering_level_for_style(&self, num_id: u32, style_id: Option<&str>) -> Option<u32> {
        let definition = self.numbering.as_ref()?.get_abstract_num_for(num_id)?;
        let mut style_id = style_id?;
        for _ in 0..self.styles.styles.len() {
            if let Some(level) = definition
                .levels
                .iter()
                .find(|level| level.p_style.as_deref() == Some(style_id))
            {
                return Some(level.ilvl);
            }
            style_id = self.styles.get_by_id(style_id)?.based_on.as_deref()?;
        }
        None
    }

    fn section_properties_in_order(&self) -> impl Iterator<Item = &CT_SectPr> {
        self.document
            .body
            .content
            .iter()
            .filter_map(|content| match content {
                BodyContent::Paragraph(paragraph) => paragraph
                    .properties
                    .as_ref()
                    .and_then(|properties| properties.sect_pr.as_ref()),
                BodyContent::Table(_) | BodyContent::ContentControl(_) | BodyContent::RawXml(_) => {
                    None
                }
            })
            .chain(self.document.body.sect_pr.iter())
    }

    // ---- Section/Page setup ----

    /// Return the number of section property owners in document order.
    pub fn section_count(&self) -> usize {
        self.section_properties_in_order().count()
    }

    /// Iterate over every section in document order.
    pub fn sections(&self) -> impl Iterator<Item = SectionRef<'_>> {
        let final_ordinal = self.section_count().checked_sub(1);
        let has_final_body_owner = self.document.body.sect_pr.is_some();
        self.section_properties_in_order()
            .enumerate()
            .map(move |(ordinal, inner)| SectionRef {
                ordinal,
                is_final: has_final_body_owner && Some(ordinal) == final_ordinal,
                inner,
            })
    }

    /// Get a section by its document-order index.
    pub fn section(&self, index: usize) -> Option<SectionRef<'_>> {
        let final_ordinal = self.section_count().checked_sub(1);
        let has_final_body_owner = self.document.body.sect_pr.is_some();
        self.section_properties_in_order()
            .nth(index)
            .map(|inner| SectionRef {
                ordinal: index,
                is_final: has_final_body_owner && Some(index) == final_ordinal,
                inner,
            })
    }

    /// Report explicit invalid or one-sided section page sizes without normalizing source.
    pub fn validate_sections(&self) -> ValidationReport {
        let mut findings = Vec::new();
        for section in self.sections() {
            let properties = section.properties();
            if properties.page_width.is_some_and(|size| size.0 <= 0)
                || properties.page_height.is_some_and(|size| size.0 <= 0)
            {
                findings.push(ValidationFinding {
                    severity: ValidationSeverity::Error,
                    message: format!("section {} has nonpositive page size", section.ordinal()),
                });
            } else if properties.page_width.is_some() != properties.page_height.is_some() {
                findings.push(ValidationFinding {
                    severity: ValidationSeverity::Warning,
                    message: format!(
                        "section {} has incomplete page size: width or height is missing",
                        section.ordinal()
                    ),
                });
            }
        }
        ValidationReport { findings }
    }

    /// Resolve the effective header or footer story for one section variant.
    pub fn section_story(
        &self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
    ) -> Result<Option<SectionStory>> {
        if section_index >= self.section_count() {
            return Err(Error::Other(format!(
                "section index {section_index} is out of range"
            )));
        }
        let mut effective = None;
        for (source_section, section) in self
            .section_properties_in_order()
            .enumerate()
            .take(section_index + 1)
        {
            let references = match kind {
                HeaderFooterKind::Header => &section.header_refs,
                HeaderFooterKind::Footer => &section.footer_refs,
            };
            if let Some(reference) = self
                .first_usable_header_footer_reference(references, hdr_type, kind.is_header())
                .cloned()
            {
                effective = Some((source_section, reference));
            }
        }
        let Some((source_section, reference)) = effective else {
            return Ok(None);
        };
        let part_name = self
            .header_footer_part_name(&reference.rel_id, kind.is_header())
            .ok_or_else(|| {
                Error::Other(format!(
                    "section story relationship {} is not a valid internal {:?}",
                    reference.rel_id, kind
                ))
            })?;
        Ok(Some(SectionStory {
            story: self.story_id_for_header_footer_part(&part_name, kind)?,
            source_section,
            inherited: source_section != section_index,
        }))
    }

    /// Ensure that one section has an explicit story, creating an empty story
    /// when the variant is absent or inherited.
    pub fn create_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
    ) -> Result<StoryId> {
        if let Some(story) = self.section_story(section_index, kind, hdr_type)?
            && !story.is_inherited()
        {
            let enabled = match hdr_type {
                HdrFtrType::Default => true,
                HdrFtrType::First => self
                    .section(section_index)
                    .is_some_and(|section| section.properties().title_pg.unwrap_or(false)),
                HdrFtrType::Even => self.even_and_odd_headers(),
            };
            if enabled {
                return Ok(story.story);
            }
            let mut candidate = if hdr_type == HdrFtrType::Even {
                self.settings_mutation_candidate()?
            } else {
                self.clone_for_staging()
            };
            match hdr_type {
                HdrFtrType::First => {
                    candidate
                        .section_mut(section_index)
                        .ok_or_else(|| {
                            Error::Other(format!("section index {section_index} is out of range"))
                        })?
                        .inner
                        .title_pg = Some(true);
                }
                HdrFtrType::Even => candidate
                    .settings
                    .get_or_insert_with(CT_Settings::new)
                    .set_even_and_odd_headers(true)?,
                HdrFtrType::Default => {}
            }
            let reopened = candidate.prepare_and_reopen_staged()?;
            let result = reopened
                .section_story(section_index, kind, hdr_type)?
                .map(|section_story| section_story.story)
                .ok_or_else(|| {
                    Error::Other("existing section story was not published".to_owned())
                })?;
            self.commit_staged_mutation(reopened);
            return Ok(result);
        }
        let mut candidate = if hdr_type == HdrFtrType::Even {
            self.settings_mutation_candidate()?
        } else {
            self.clone_for_staging()
        };
        if hdr_type == HdrFtrType::Even {
            candidate
                .settings
                .get_or_insert_with(CT_Settings::new)
                .set_even_and_odd_headers(true)?;
        }
        candidate.flush_to_package()?;
        let story = candidate.install_empty_section_story(section_index, kind, hdr_type)?;
        candidate.reconcile_comment_removal(self)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        let result = reopened
            .section_story(section_index, kind, hdr_type)?
            .map(|section_story| section_story.story)
            .ok_or_else(|| Error::Other("created section story was not published".to_owned()))?;
        debug_assert_eq!(result.part_name(), story.part_name());
        self.commit_staged_mutation(reopened);
        Ok(result)
    }

    /// Point one section variant at an existing same-kind story in this document.
    pub fn link_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
        story: &StoryId,
    ) -> Result<StoryId> {
        let mut candidate = self.clone_for_staging();
        candidate.flush_to_package()?;
        candidate.validate_section_story_target(story, kind)?;
        let relationship_id = candidate.document_story_relationship(kind, story.part_name())?;
        let removed = candidate.set_direct_section_story_reference(
            section_index,
            kind,
            hdr_type,
            Some(relationship_id),
        )?;
        candidate.prune_unreachable_authored_section_stories(&removed)?;
        candidate.reconcile_comment_removal(self)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        let result = reopened
            .section_story(section_index, kind, hdr_type)?
            .map(|section_story| section_story.story)
            .ok_or_else(|| Error::Other("linked section story was not published".to_owned()))?;
        self.commit_staged_mutation(reopened);
        Ok(result)
    }

    /// Remove the direct reference so the same variant inherits from the
    /// nearest preceding section, or remains absent when none exists.
    pub fn inherit_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
    ) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.flush_to_package()?;
        let removed =
            candidate.set_direct_section_story_reference(section_index, kind, hdr_type, None)?;
        candidate.prune_unreachable_authored_section_stories(&removed)?;
        candidate.reconcile_comment_removal(self)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        self.commit_staged_mutation(reopened);
        Ok(())
    }

    /// Clone the effective story into an independent story owned by this section.
    pub fn unlink_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
    ) -> Result<StoryId> {
        let effective = self
            .section_story(section_index, kind, hdr_type)?
            .ok_or_else(|| Error::Other("cannot unlink an absent section story".to_owned()))?;
        self.replace_section_story(section_index, kind, hdr_type, effective.story())
    }

    /// Replace one variant with an independent copy of an existing same-kind story.
    pub fn replace_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
        source: &StoryId,
    ) -> Result<StoryId> {
        let mut candidate = self.clone_for_staging();
        candidate.flush_to_package()?;
        candidate.validate_section_story_target(source, kind)?;
        let part_name = candidate.clone_header_footer_story_part(source.part_name(), kind)?;
        let relationship_id = candidate.document_story_relationship(kind, &part_name)?;
        let removed = candidate.set_direct_section_story_reference(
            section_index,
            kind,
            hdr_type,
            Some(relationship_id),
        )?;
        candidate.prune_unreachable_authored_section_stories(&removed)?;
        candidate.reconcile_comment_removal(self)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        let result = reopened
            .section_story(section_index, kind, hdr_type)?
            .map(|section_story| section_story.story)
            .ok_or_else(|| Error::Other("replaced section story was not published".to_owned()))?;
        self.commit_staged_mutation(reopened);
        Ok(result)
    }

    /// Replace one section variant with a distinct empty story.
    pub fn remove_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
    ) -> Result<StoryId> {
        let mut candidate = self.clone_for_staging();
        candidate.flush_to_package()?;
        candidate.install_empty_section_story(section_index, kind, hdr_type)?;
        candidate.reconcile_comment_removal(self)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        let result = reopened
            .section_story(section_index, kind, hdr_type)?
            .map(|section_story| section_story.story)
            .ok_or_else(|| Error::Other("empty section story was not published".to_owned()))?;
        self.commit_staged_mutation(reopened);
        Ok(result)
    }

    fn story_id_for_header_footer_part(
        &self,
        part_name: &str,
        kind: HeaderFooterKind,
    ) -> Result<StoryId> {
        let xml = self
            .package
            .get_part(part_name)
            .ok_or_else(|| Error::Other(format!("section story part {part_name} is missing")))?;
        let story_kind = kind.story_kind();
        let owner = scan_story_owners(xml, story_kind)?
            .into_iter()
            .find(|owner| owner.kind == story_kind)
            .ok_or_else(|| Error::Other(format!("section story part {part_name} has no root")))?;
        Ok(StoryId {
            kind: story_kind,
            part_name: part_name.to_owned(),
            owner_index: owner.owner_index,
            fingerprint: owner.fingerprint,
        })
    }

    fn validate_section_story_target(&self, story: &StoryId, kind: HeaderFooterKind) -> Result<()> {
        if story.kind != kind.story_kind() {
            return Err(StoryError::WrongOwner {
                expected: kind.story_kind(),
                actual: story.kind,
            }
            .into());
        }
        let (_, owner) = self.story_source_and_owner(story)?;
        if owner.kind != kind.story_kind() || owner.owner_index != 0 {
            return Err(Error::Other(
                "section story target must be the physical header or footer root".to_owned(),
            ));
        }
        Ok(())
    }

    fn document_story_relationship(
        &mut self,
        kind: HeaderFooterKind,
        part_name: &str,
    ) -> Result<String> {
        if let Some(id) = self
            .package
            .get_part_rels(&self.doc_part_name)
            .and_then(|relationships| {
                relationships.items.iter().find(|relationship| {
                    relationship.rel_type == kind.relationship_type()
                        && relationship_is_internal(relationship)
                        && part_name_identity(&OpcPackage::resolve_rel_target(
                            &self.doc_part_name,
                            &relationship.target,
                        )) == part_name_identity(part_name)
                })
            })
            .map(|relationship| relationship.id.clone())
        {
            return Ok(id);
        }
        let id = self
            .identifiers
            .reserve_relationship_id_checked(&self.doc_part_name)?;
        let target = relative_target(&self.doc_part_name, part_name);
        self.package
            .get_or_create_part_rels(&self.doc_part_name)
            .add_with_id(&id, kind.relationship_type(), &target);
        Ok(id)
    }

    fn set_direct_section_story_reference(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
        relationship_id: Option<String>,
    ) -> Result<Vec<HdrFtrRef>> {
        let section = self.section_mut(section_index).ok_or_else(|| {
            Error::Other(format!("section index {section_index} is out of range"))
        })?;
        let references = match kind {
            HeaderFooterKind::Header => &mut section.inner.header_refs,
            HeaderFooterKind::Footer => &mut section.inner.footer_refs,
        };
        let mut removed = Vec::new();
        references.retain(|reference| {
            if reference.hdr_ftr_type == hdr_type {
                removed.push(reference.clone());
                false
            } else {
                true
            }
        });
        if let Some(rel_id) = relationship_id {
            references.push(HdrFtrRef {
                hdr_ftr_type: hdr_type,
                rel_id,
            });
            if hdr_type == HdrFtrType::First {
                section.inner.title_pg = Some(true);
            }
        }
        Ok(removed)
    }

    fn install_empty_section_story(
        &mut self,
        section_index: usize,
        kind: HeaderFooterKind,
        hdr_type: HdrFtrType,
    ) -> Result<StoryId> {
        let xml = Self::serialize_hdr_ftr(&CT_HdrFtr::new(), kind.is_header())?;
        let part_name = self.install_header_footer_story_part(xml, None, kind)?;
        let relationship_id = self.document_story_relationship(kind, &part_name)?;
        let removed = self.set_direct_section_story_reference(
            section_index,
            kind,
            hdr_type,
            Some(relationship_id),
        )?;
        self.prune_unreachable_authored_section_stories(&removed)?;
        self.story_id_for_header_footer_part(&part_name, kind)
    }

    fn clone_header_footer_story_part(
        &mut self,
        source_part: &str,
        kind: HeaderFooterKind,
    ) -> Result<String> {
        let xml = self
            .package
            .get_part(source_part)
            .ok_or_else(|| Error::Other(format!("section story part {source_part} is missing")))?;
        if !header_footer_story_has_expected_root(xml, kind.is_header()) {
            return Err(Error::Other(format!(
                "section story part {source_part} has the wrong root"
            )));
        }
        let mut xml = xml.to_vec();
        xml = rewrite_authored_doc_pr_ids(&xml, &mut self.identifiers.drawing_ids)?;
        let relationships = self.package.get_part_rels(source_part).cloned();
        self.install_header_footer_story_part(
            xml,
            relationships.as_ref().map(|rels| (source_part, rels)),
            kind,
        )
    }

    fn install_header_footer_story_part(
        &mut self,
        xml: Vec<u8>,
        copied_relationships: Option<(&str, &oxml_opc::relationship::Relationships)>,
        kind: HeaderFooterKind,
    ) -> Result<String> {
        let part_name = self
            .identifiers
            .reserve_part_name("/word", kind.part_stem(), "xml")?;
        self.package.set_part(&part_name, xml);
        self.package
            .content_types
            .add_override(&part_name, kind.content_type());
        self.identifiers.register_content_type_override(&part_name);
        self.identifiers
            .authored_story_parts
            .insert(part_name.clone());

        if let Some((source_part, relationships)) = copied_relationships {
            let mut relationships = relationships.clone();
            for relationship in &mut relationships.items {
                if relationship_is_internal(relationship) {
                    let target = OpcPackage::resolve_rel_target(source_part, &relationship.target);
                    relationship.target = relative_target(&part_name, &target);
                }
            }
            let owner = relationship_owner_identity(&part_name);
            let ids = relationships
                .items
                .iter()
                .map(|relationship| relationship.id.clone())
                .collect::<HashSet<_>>();
            self.identifiers
                .relationship_ids
                .insert(owner.clone(), ids.clone());
            if !ids.is_empty() {
                self.identifiers
                    .authored_story_relationship_ids
                    .insert(owner, ids);
            }
            self.package.set_part_rels(&part_name, relationships);
        }
        Ok(part_name)
    }

    /// Get a mutable section by its document-order index.
    pub fn section_mut(&mut self, index: usize) -> Option<Section<'_>> {
        let count = self.section_count();
        let has_final_body_owner = self.document.body.sect_pr.is_some();
        if index >= count {
            return None;
        }
        self.invalidate_layout();
        let mut remaining = index;
        for content in &mut self.document.body.content {
            if let BodyContent::Paragraph(paragraph) = content
                && let Some(inner) = paragraph
                    .properties
                    .as_mut()
                    .and_then(|properties| properties.sect_pr.as_mut())
            {
                if remaining == 0 {
                    return Some(Section {
                        ordinal: index,
                        is_final: has_final_body_owner && index + 1 == count,
                        inner,
                    });
                }
                remaining -= 1;
            }
        }
        self.document.body.sect_pr.as_mut().map(|inner| Section {
            ordinal: index,
            is_final: has_final_body_owner && index + 1 == count,
            inner,
        })
    }

    /// Insert an empty section at a document-order index.
    ///
    /// `index == section_count()` appends a new final section. Larger indices
    /// are rejected without changing the document.
    pub fn insert_section(&mut self, index: usize) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        candidate.insert_section_in_place(index)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        self.commit_staged_mutation(reopened);
        Ok(())
    }

    /// Remove a section by document-order index and merge its content.
    ///
    /// A non-final section merges into the following section. Removing the
    /// final section promotes the preceding section properties to the final
    /// body owner. The sole section cannot be removed.
    pub fn remove_section(&mut self, index: usize) -> Result<()> {
        let mut candidate = self.clone_for_staging();
        let removed_references = candidate.remove_section_in_place(index)?;
        candidate.prune_unreachable_authored_section_stories(&removed_references)?;
        candidate.reconcile_comment_removal(self)?;
        let reopened = candidate.prepare_and_reopen_staged()?;
        self.commit_staged_mutation(reopened);
        Ok(())
    }

    fn insert_section_in_place(&mut self, index: usize) -> Result<()> {
        let count = self.section_count();
        if index > count {
            return Err(Error::Other(format!(
                "section index {index} is out of bounds for insertion into {count} sections"
            )));
        }
        // Copy resolved geometry only. Relationship owners and other section
        // policies belong to the old section and must not be cloned.
        let previous = self
            .section(index.saturating_sub(1))
            .map(|s| s.properties());
        let mut inserted = empty_section_properties();
        inserted.page_width = Some(previous.and_then(|s| s.page_width).unwrap_or(Twips(12240)));
        inserted.page_height = Some(previous.and_then(|s| s.page_height).unwrap_or(Twips(15840)));
        inserted.orientation = Some(
            previous
                .and_then(|s| s.orientation)
                .unwrap_or(ST_PageOrientation::Portrait),
        );
        inserted.margin_top = Some(previous.and_then(|s| s.margin_top).unwrap_or(Twips(1440)));
        inserted.margin_right = Some(previous.and_then(|s| s.margin_right).unwrap_or(Twips(1440)));
        inserted.margin_bottom = Some(
            previous
                .and_then(|s| s.margin_bottom)
                .unwrap_or(Twips(1440)),
        );
        inserted.margin_left = Some(previous.and_then(|s| s.margin_left).unwrap_or(Twips(1440)));
        inserted.gutter = Some(previous.and_then(|s| s.gutter).unwrap_or(Twips(0)));
        inserted.header_distance = Some(
            previous
                .and_then(|s| s.header_distance)
                .unwrap_or(Twips(720)),
        );
        inserted.footer_distance = Some(
            previous
                .and_then(|s| s.footer_distance)
                .unwrap_or(Twips(720)),
        );
        self.invalidate_layout();
        if count == 0 {
            self.document.body.sect_pr = Some(inserted);
            return Ok(());
        }
        if index == count {
            let previous_final = self.document.body.sect_pr.take().ok_or_else(|| {
                Error::Other("document section ownership changed during insertion".to_owned())
            })?;
            let mut paragraph = CT_P::new();
            paragraph.properties = Some(CT_PPr {
                sect_pr: Some(previous_final),
                ..CT_PPr::default()
            });
            self.document
                .body
                .content
                .push(BodyContent::Paragraph(Box::new(paragraph)));
            self.document.body.sect_pr = Some(inserted);
            return Ok(());
        }

        let insert_at = if index == 0 {
            0
        } else {
            self.paragraph_section_owner_index(index - 1)
                .ok_or_else(|| {
                    Error::Other("document section ownership changed during insertion".to_owned())
                })?
                + 1
        };
        let mut paragraph = CT_P::new();
        paragraph.properties = Some(CT_PPr {
            sect_pr: Some(inserted),
            ..CT_PPr::default()
        });
        self.document
            .body
            .content
            .insert(insert_at, BodyContent::Paragraph(Box::new(paragraph)));
        Ok(())
    }

    fn remove_section_in_place(&mut self, index: usize) -> Result<Vec<HdrFtrRef>> {
        let count = self.section_count();
        if count <= 1 {
            return Err(Error::Other(
                "the sole document section cannot be removed".to_owned(),
            ));
        }
        if index >= count {
            return Err(Error::Other(format!(
                "section index {index} is out of bounds for {count} sections"
            )));
        }
        let removed_section = self
            .section(index)
            .expect("validated section index")
            .properties();
        let removed = removed_section
            .header_refs
            .iter()
            .chain(&removed_section.footer_refs)
            .cloned()
            .collect::<Vec<_>>();
        self.invalidate_layout();

        if index + 1 < count {
            let mut effective_headers: [Option<HdrFtrRef>; 3] = [None, None, None];
            let mut effective_footers: [Option<HdrFtrRef>; 3] = [None, None, None];
            for section in self.section_properties_in_order().take(index + 1) {
                for hdr_type in [HdrFtrType::Default, HdrFtrType::First, HdrFtrType::Even] {
                    let slot = header_type_index(hdr_type);
                    if let Some(reference) = self.first_usable_header_footer_reference(
                        &section.header_refs,
                        hdr_type,
                        true,
                    ) {
                        effective_headers[slot] = Some(reference.clone());
                    }
                    if let Some(reference) = self.first_usable_header_footer_reference(
                        &section.footer_refs,
                        hdr_type,
                        false,
                    ) {
                        effective_footers[slot] = Some(reference.clone());
                    }
                }
            }
            let following = self
                .section(index + 1)
                .expect("every non-final section has a following section");
            let mut following_header_overrides = [false; 3];
            let mut following_footer_overrides = [false; 3];
            for hdr_type in [HdrFtrType::Default, HdrFtrType::First, HdrFtrType::Even] {
                let slot = header_type_index(hdr_type);
                following_header_overrides[slot] = self
                    .first_usable_header_footer_reference(
                        &following.properties().header_refs,
                        hdr_type,
                        true,
                    )
                    .is_some();
                following_footer_overrides[slot] = self
                    .first_usable_header_footer_reference(
                        &following.properties().footer_refs,
                        hdr_type,
                        false,
                    )
                    .is_some();
            }
            let mut following = self
                .section_mut(index + 1)
                .expect("every non-final section has a following section");
            for (slot, inherited) in effective_headers.into_iter().enumerate() {
                if !following_header_overrides[slot]
                    && let Some(inherited) = inherited
                {
                    following.properties_mut().header_refs.push(inherited);
                }
            }
            for (slot, inherited) in effective_footers.into_iter().enumerate() {
                if !following_footer_overrides[slot]
                    && let Some(inherited) = inherited
                {
                    following.properties_mut().footer_refs.push(inherited);
                }
            }
        }

        if index + 1 < count || self.document.body.sect_pr.is_none() {
            let owner_index = self
                .paragraph_section_owner_index(index)
                .expect("every non-final section has a paragraph owner");
            let remove_empty_owner = {
                let BodyContent::Paragraph(paragraph) =
                    &mut self.document.body.content[owner_index]
                else {
                    unreachable!("recorded section owner is not a paragraph")
                };
                let properties = paragraph
                    .properties
                    .as_mut()
                    .expect("a section owner has paragraph properties");
                properties.sect_pr = None;
                if *properties == CT_PPr::default() {
                    paragraph.properties = None;
                }
                *paragraph == Box::default()
            };
            if remove_empty_owner {
                self.document.body.content.remove(owner_index);
            }
        } else {
            let previous_owner = self
                .paragraph_section_owner_index(index - 1)
                .expect("a removable final section has a preceding paragraph owner");
            let (promoted, remove_empty_owner) = {
                let BodyContent::Paragraph(paragraph) =
                    &mut self.document.body.content[previous_owner]
                else {
                    unreachable!("recorded section owner is not a paragraph")
                };
                let properties = paragraph
                    .properties
                    .as_mut()
                    .expect("a section owner has paragraph properties");
                let promoted = properties
                    .sect_pr
                    .take()
                    .expect("recorded section properties disappeared");
                if *properties == CT_PPr::default() {
                    paragraph.properties = None;
                }
                (promoted, *paragraph == Box::default())
            };
            if remove_empty_owner {
                self.document.body.content.remove(previous_owner);
            }
            self.document.body.sect_pr = Some(promoted);
        }
        Ok(removed)
    }

    fn paragraph_section_owner_index(&self, ordinal: usize) -> Option<usize> {
        self.document
            .body
            .content
            .iter()
            .enumerate()
            .filter(|(_, content)| {
                matches!(
                    content,
                    BodyContent::Paragraph(paragraph)
                        if paragraph
                            .properties
                            .as_ref()
                            .is_some_and(|properties| properties.sect_pr.is_some())
                )
            })
            .nth(ordinal)
            .map(|(index, _)| index)
    }

    fn prune_unreachable_authored_section_stories(&mut self, removed: &[HdrFtrRef]) -> Result<()> {
        let modeled_ids = self.main_story_relationship_ids();
        let mut active_ids = modeled_ids
            .iter()
            .map(String::as_str)
            .collect::<HashSet<_>>();
        let opaque_ids = self.opaque_relationship_ids_from_serialized_story(&modeled_ids)?;
        active_ids.extend(opaque_ids.iter().map(String::as_str));
        // Imported producer parts stay in the package. Retire only their qualified
        // marker spans when no modeled, inherited or opaque physical use survives.
        let retired_targets = removed
            .iter()
            .map(|reference| {
                let relationship = self
                    .package
                    .get_part_rels(&self.doc_part_name)
                    .and_then(|rels| rels.items.iter().find(|rel| rel.id == reference.rel_id))
                    .ok_or_else(|| {
                        Error::Other(format!(
                            "retired section relationship {} is missing",
                            reference.rel_id
                        ))
                    })?;
                if !relationship_is_internal(relationship)
                    || !matches!(
                        relationship.rel_type.as_str(),
                        rel_types::HEADER | rel_types::FOOTER
                    )
                {
                    return Err(Error::Other(
                        "retired section relationship is not an internal story".into(),
                    ));
                }
                Ok(OpcPackage::resolve_rel_target(
                    &self.doc_part_name,
                    &relationship.target,
                ))
            })
            .collect::<Result<HashSet<_>>>()?;
        for target in retired_targets {
            let identity = part_name_identity(&target);
            let mut used = false;
            for (owner, relationships) in &self.package.part_rels {
                for relationship in &relationships.items {
                    if !relationship_is_internal(relationship)
                        || part_name_identity(&OpcPackage::resolve_rel_target(
                            owner,
                            &relationship.target,
                        )) != identity
                    {
                        continue;
                    }
                    if part_name_identity(owner) == part_name_identity(&self.doc_part_name) {
                        used |= active_ids.contains(relationship.id.as_str());
                    } else {
                        let xml = self.package.get_part(owner).ok_or_else(|| {
                            Error::Other(format!(
                                "cannot prove incoming section-story ownership from missing {owner}"
                            ))
                        })?;
                        if !xml_relationship_ids_in_order(xml)?.contains(&relationship.id) {
                            return Err(Error::Other(format!(
                                "cannot prove opaque incoming section-story relationship {} from {owner}",
                                relationship.id
                            )));
                        }
                        used = true;
                    }
                }
            }
            if !used && let Some(xml) = self.package.get_part(&target) {
                let omitted = Self::omit_comment_markers(xml)?;
                if omitted != xml {
                    set_story_source_xml(self, &target, omitted)?;
                }
            }
        }
        let removable_ids = removed
            .iter()
            .map(|reference| reference.rel_id.as_str())
            .filter(|id| !active_ids.contains(id))
            .collect::<HashSet<_>>();
        let candidates = self
            .package
            .get_part_rels(&self.doc_part_name)
            .into_iter()
            .flat_map(|relationships| &relationships.items)
            .filter(|relationship| {
                removable_ids.contains(relationship.id.as_str())
                    && relationship_is_internal(relationship)
                    && matches!(
                        relationship.rel_type.as_str(),
                        rel_types::HEADER | rel_types::FOOTER
                    )
            })
            .map(|relationship| {
                (
                    relationship.id.clone(),
                    OpcPackage::resolve_rel_target(&self.doc_part_name, &relationship.target),
                )
            })
            .filter(|(_, target)| self.identifiers.authored_story_parts.contains(target))
            .collect::<Vec<_>>();

        for (relationship_id, target) in candidates {
            if let Some(relationships) = self.package.get_part_rels_mut(&self.doc_part_name) {
                relationships
                    .items
                    .retain(|relationship| relationship.id != relationship_id);
            }
            self.identifiers
                .retire_authored_story_relationships(&self.doc_part_name, [relationship_id]);
            let target_identity = part_name_identity(&target);
            let still_referenced = self.package.part_rels.iter().any(|(owner, relationships)| {
                relationships.items.iter().any(|relationship| {
                    relationship_is_internal(relationship)
                        && part_name_identity(&OpcPackage::resolve_rel_target(
                            owner,
                            &relationship.target,
                        )) == target_identity
                })
            });
            if still_referenced {
                continue;
            }
            self.clear_authored_story_relationships(&target);
            self.package.remove_part(&target);
            self.package.remove_part_rels(&target);
            self.package.content_types.remove_override(&target);
            self.identifiers.authored_story_parts.remove(&target);
            self.identifiers.retire_authored_part(&target);
        }
        Ok(())
    }

    /// Get the section properties (page size, margins).
